// Both should suppress iframe rendering and show the empty-state card.
const HAS_SOURCE = D.meta.project !== "(no source yet)" && !!D.meta.sourceEntry;
// Cache-bust source iframes so edits to source files show up on editor reload.
const EDITOR_SESSION = Date.now().toString(36);

