  const doc = iframeEl.contentDocument;
  if (!win || !doc) return;
  // Initial fire - covers the fast-mount case where React is already done by
  // load (cached iframe, small components, etc.).
  try { win.eval(script); } catch (_) { /* cross-origin or syntax */ }

  // Re-fire on every DOM mutation in the iframe body for the next 3 seconds.
  // Each fire is a no-op if the state is already correct, so the cost is
  // negligible. Disconnect once the budget is exhausted.
  const target = doc.body || doc.documentElement;
  if (!target || typeof MutationObserver !== "function") return;
  let fires = 0;
  const MAX_FIRES = 8;        // hard cap on re-evals (each one queues its own 3s rAF retry chain)
