// separator to keep the rest of the ID intact.
const splitCommentKey = (key) => {
  const i = key.indexOf(":");
  return i < 0 ? [key, ""] : [key.slice(0, i), key.slice(i + 1)];
};
const splitFieldRef = (ref) => {
  // `<entityId>.<fieldName>` - split on the *last* `.` so entity IDs with dots
  // (e.g. `User.v2`) still resolve correctly.
  const i = ref.lastIndexOf(".");
  return i < 0 ? [ref, ""] : [ref.slice(0, i), ref.slice(i + 1)];
};

// ─────── Edge routing ───────
// Pick the connection side on each rect based on the direction toward the
// other rect's centre, then build cubic-bezier control points along the chosen
// sides' outward normals. The curve enters/leaves perpendicular to each edge,
// which is what makes the arrow head land cleanly even when nodes aren't
// orthogonally aligned. Returns the 4 path points + the chosen sides.
//   A, B: { x, y, w, h }
//   opts.tensionMin / tensionMax: control-point distance bounds (default 40, 180)
function routeEdge(A, B, opts = {}) {
  const ax = A.x + A.w / 2, ay = A.y + A.h / 2;
  const bx = B.x + B.w / 2, by = B.y + B.h / 2;
  // Pick a side of `rect` whose centre faces (towardX, towardY) most closely.
  // Compare |Δy|·w vs |Δx|·h - whichever is larger picks the horizontal or
  // vertical axis (the one where the target lies "more outside" the rect).
  const sideOf = (rect, towardX, towardY) => {
    const cx = rect.x + rect.w / 2, cy = rect.y + rect.h / 2;
    const ddx = towardX - cx, ddy = towardY - cy;
    if (Math.abs(ddy) * rect.w > Math.abs(ddx) * rect.h) return ddy > 0 ? "bottom" : "top";
    return ddx > 0 ? "right" : "left";
  };
  // `t` is the parametric position along the chosen side (0 = top/left corner,
  // 1 = bottom/right corner). Default 0.5 = side centre. Callers passing
  // {exitT, entryT} can spread parallel anchors evenly across a side.
  const ptOf = (rect, side, t = 0.5) => {
    switch (side) {
      case "right":  return { x: rect.x + rect.w,         y: rect.y + rect.h * t, nx:  1, ny:  0 };
      case "left":   return { x: rect.x,                  y: rect.y + rect.h * t, nx: -1, ny:  0 };
      case "bottom": return { x: rect.x + rect.w * t,     y: rect.y + rect.h,     nx:  0, ny:  1 };
      case "top":    return { x: rect.x + rect.w * t,     y: rect.y,              nx:  0, ny: -1 };
    }
  };
  const sideA = opts.sideA ?? sideOf(A, bx, by);
  const sideB = opts.sideB ?? sideOf(B, ax, ay);
  const A0 = ptOf(A, sideA, opts.exitT  ?? 0.5);
  const B0 = ptOf(B, sideB, opts.entryT ?? 0.5);
  // Tension = how far the control points extend from each end along the normal.
  // 40% of centre-to-centre distance, clamped, gives a smooth perpendicular
  // approach without looping (near nodes) or overshooting (distant nodes).
  const tMin = opts.tensionMin ?? 40;
  const tMax = opts.tensionMax ?? 180;
  const tension = Math.max(tMin, Math.min(tMax, Math.hypot(bx - ax, by - ay) * 0.4));
  return {
    fx: A0.x, fy: A0.y, tx: B0.x, ty: B0.y,
    c1x: A0.x + A0.nx * tension, c1y: A0.y + A0.ny * tension,
    c2x: B0.x + B0.nx * tension, c2y: B0.y + B0.ny * tension,
    sideA, sideB,
  };
}

// Route a batch of arrows so that parallel anchors on the same (rect, side)
// pair don't stack at one point. 3-pass: pick sides → count anchors per
// (rectId, side) → place each anchor at slot (idx+1)/(total+1) of the side.
// `arrows` is [{from, to, ...}], `getRect(id)` returns the rect for that id.
function routeEdges(arrows, getRect, opts = {}) {
  // Pass 1: compute sides for each edge via a probe call.
  const sides = arrows.map(a => {
    const A = getRect(a.from), B = getRect(a.to);
    if (!A || !B) return null;
    const probe = routeEdge(A, B, opts);
    return { sideA: probe.sideA, sideB: probe.sideB };
  });
  // Pass 2: count anchors per (rect, side) on both ends.
  const counts = new Map();
  const inc = (k) => counts.set(k, (counts.get(k) || 0) + 1);
  sides.forEach((r, i) => {
    if (!r) return;
    inc(arrows[i].from + ":out:" + r.sideA);
    inc(arrows[i].to   + ":in:"  + r.sideB);
  });
  // Pass 3: place each edge with its slot index/total.
  const used = new Map();
  return arrows.map((a, i) => {
    const r = sides[i]; if (!r) return null;
    const A = getRect(a.from), B = getRect(a.to);
    const outKey = a.from + ":out:" + r.sideA;
    const inKey  = a.to   + ":in:"  + r.sideB;
    const outTotal = counts.get(outKey), inTotal = counts.get(inKey);
    const outIdx = used.get(outKey) || 0, inIdx = used.get(inKey) || 0;
    used.set(outKey, outIdx + 1);
    used.set(inKey,  inIdx  + 1);
    const exitT  = (outIdx + 1) / (outTotal + 1);
    const entryT = (inIdx  + 1) / (inTotal  + 1);
    return routeEdge(A, B, { ...opts, sideA: r.sideA, sideB: r.sideB, exitT, entryT });
  });
}

// Point on cubic at parameter t ∈ [0, 1].
function cubicPt(e, t) {
  const u = 1 - t;
  return {
    x: u*u*u*e.fx + 3*u*u*t*e.c1x + 3*u*t*t*e.c2x + t*t*t*e.tx,
    y: u*u*u*e.fy + 3*u*u*t*e.c1y + 3*u*t*t*e.c2y + t*t*t*e.ty,
  };
}

// Estimated bbox for a chip-style label centred at `pt`. We can't ask the DOM
// for `getBBox` at layout time (text isn't rendered yet), so we approximate
// from char count. Tuned to *over-estimate* for Inter 11px so the chip
// background never crops the rendered text (previous 6.4px/14px values were
// too tight - rendered glyphs are wider than that on average and the text
// spilled below/right of the chip). The chip uses display: flex; place-items:
// center; in CSS so any extra slack just shows as padding, never as overflow.
function labelBBox(pt, text, opts = {}) {
  const maxW = opts.maxWidth ?? 160;
  const charW = opts.charW ?? 7.2;     // Inter 11px upper bound across glyphs
  const lineH = opts.lineH ?? 16;
  const padX = opts.padX ?? 18;
  const padY = opts.padY ?? 10;
  const minW = opts.minW ?? 48;
  const t = String(text || "");
  const naturalW = t.length * charW + padX;
  const w = Math.min(maxW, Math.max(minW, naturalW));
  const lines = naturalW > maxW ? Math.ceil(naturalW / (maxW - padX)) : 1;
  const h = lines * lineH + padY;
  return { x: pt.x - w/2, y: pt.y - h/2, w, h, cx: pt.x, cy: pt.y };
}

const rectsOverlap = (a, b, pad = 4) =>
  !(a.x + a.w + pad < b.x || b.x + b.w + pad < a.x ||
    a.y + a.h + pad < b.y || b.y + b.h + pad < a.y);

// Place a chip label along an edge curve so it avoids `obstacles` (other
// already-placed labels + node rects). Tries the canonical t-values in order
// of "centeredness" first, then falls back to a perpendicular offset on the
// best candidate. Returns { pt, bbox, t, offset }.
function placeLabel(edge, text, obstacles, opts = {}) {
  const tries = opts.tries ?? [0.5, 0.42, 0.58, 0.34, 0.66, 0.28, 0.72];
  const perpAmts = opts.perpAmts ?? [0, -16, 16, -28, 28];
  for (const perp of perpAmts) {
    for (const t of tries) {
      const pt = cubicPt(edge, t);
      // Compute the curve's tangent at t (approximate via secant) so we can
      // shift perpendicular to it for the `perp` offset.
      const dt = 0.01;
      const p2 = cubicPt(edge, Math.min(1, t + dt));
      const dx = p2.x - pt.x, dy = p2.y - pt.y;
      const len = Math.hypot(dx, dy) || 1;
      const nx = -dy / len, ny = dx / len; // perpendicular unit
      const offsetPt = { x: pt.x + nx * perp, y: pt.y + ny * perp };
      const bbox = labelBBox(offsetPt, text, opts);
      if (!obstacles.some(o => rectsOverlap(bbox, o))) {
        return { pt: offsetPt, bbox, t, perp };
      }
    }
  }
  // Nothing fits - just use the centre with no offset. The chip will overlap
  // something, but at least it stays attached to its curve and doesn't drift
  // off into nothing.
  const pt = cubicPt(edge, 0.5);
  return { pt, bbox: labelBBox(pt, text, opts), t: 0.5, perp: 0 };
}

