  Tablet:   () => html`<svg viewBox="0 0 16 16" width="14" height="14" ...${stroke}><rect x="4" y="2" width="8" height="12" rx="1.2"/><circle cx="8" cy="12" r="0.5" fill="currentColor"/></svg>`,
