/* WS-BROWSER - Explainer card on the onboarding final step for Browser use.
   Woven drives the user's REAL Chrome via the Chrome DevTools MCP (CDP) - there
   is no extension to install. Claude Code wires it automatically for browser
   tasks (e.g. testing nodes with URLs); Codex CLI cannot drive a browser. */
function OnboardingBrowserCard() {
  return html`
    <div className="model-setup-xcard">
      <div className="model-setup-xcard-head">
        <span className="model-setup-xcard-glyph"><${Icon.Globe}/></span>
        <div className="model-setup-xcard-text">
          <div className="model-setup-xcard-title">Browser use <span className="model-setup-choice-tag is-soft">optional</span></div>
          <div className="model-setup-xcard-desc">Let the agent see + click a real browser - for testing prototypes and live research. It drives your own Chrome, so cookies and logins carry over.</div>
        </div>
      </div>
      <div className="model-setup-xcard-steps">
        <div className="model-setup-xcard-step"><span className="model-setup-xcard-step-n">1</span><span>Start Chrome with remote debugging: <code>--remote-debugging-port=9222</code>.</span></div>
        <div className="model-setup-xcard-step"><span className="model-setup-xcard-step-n">2</span><span>Run a Testing node (or any browser task) - Woven wires the <strong>Chrome DevTools MCP</strong> automatically.</span></div>
        <div className="model-setup-xcard-step"><span className="model-setup-xcard-step-n">3</span><span>The agent screenshots + clicks your pages by sight.</span></div>
      </div>
      <div className="model-setup-xcard-foot">No extension needed. Claude Code only - Codex and opencode CLIs can't drive a browser yet.</div>
    </div>
  `;
}

/* v3.4.43 - Lightweight install-instructions popup opened from Step 1's CTA.
   Shows the two CLI install paths (Claude Code · Codex) as copy-paste blocks
   plus an "Or paste an API key" button that opens the existing Settings
   dialog. No inline form, no separate picker - one place, three commands,
   done. */
function ModelInstallDialog({ onClose, onRefresh }) {
  const cmds = [
    { label: "Claude Code (Anthropic)", install: "npm install -g @anthropic-ai/claude-code", login: "claude login" },
    { label: "Codex (OpenAI)",          install: "npm install -g @openai/codex",            login: "codex login" },
    { label: "opencode (multi-provider)", install: "brew install sst/tap/opencode",          login: "opencode auth login" },
  ];
  const [copied, setCopied] = useState(null);
  const copy = (text, id) => {
    try { navigator.clipboard.writeText(text); setCopied(id); setTimeout(() => setCopied(c => c === id ? null : c), 1400); } catch {}
  };
  return createPortal(html`
    <div className="workflow-modal-backdrop" onClick=${onClose}>
      <div className="workflow-modal model-install-modal" onClick=${e => e.stopPropagation()}>
        <div className="workflow-modal-head">
          <div>
            <div className="workflow-modal-title">Install a model CLI</div>
            <div className="workflow-modal-sub">Pick one - you only need one path to a model.</div>
          </div>
          <button type="button" className="workflow-modal-close" onClick=${onClose} aria-label="Close">×</button>
        </div>
        <div className="model-install-modal-body">
          ${cmds.map((c, i) => html`
            <div className="model-install-modal-row" key=${c.label}>
              <div className="model-install-modal-name">${c.label}</div>
              ${[c.install, c.login].map((cmd, j) => html`
                <div className="model-install-modal-cmd" key=${j}>
                  <code>${cmd}</code>
                  <button
                    type="button"
                    className="model-install-modal-copy"
                    onClick=${() => copy(cmd, `${i}-${j}`)}
                  >${copied === `${i}-${j}` ? "Copied" : "Copy"}</button>
                </div>
              `)}
            </div>
          `)}
        </div>
        <div className="model-install-modal-foot">
          <button type="button" className="model-setup-wizard-nav" onClick=${onClose}>Close</button>
          <button type="button" className="model-setup-wizard-nav is-primary" onClick=${onRefresh}>I've installed it · refresh</button>
        </div>
      </div>
    </div>
  `, document.body);
}

/* Full-page project browser. Rendered at /editor/ when in workspace mode
   with no ?project= in the URL. Card grid scales to N projects; click a
   card to enter the project (URL gets ?project=<id>), hover for rename/
   delete actions, big "+ New project" tile at the end. */
// ─── SystemLanding ────────────────────────────────────────────────────────
// v3.3 - System reference surface. Sidebar nav with 4 sections:
//   1. Orchestrators      - the new toggleable orchestrator registry
//   2. Skills        - the 14 generator skills (Pathway A vendor API or B Claude-writes)
//   3. Subagents     - every .claude/agents/*.md, grouped by family
//   4. Node kinds    - registry.py KINDS, grouped by category
//
// Each subview renders differently. Skills + Subagents + Node kinds are
// read-only reference; Orchestrators has its toggle. State lives here; sidebar
// items show counts so the user knows the size of each surface before clicking.
// ─── Workspace SYSTEM AGENT threads - shared infrastructure ────────────────
// v3.13 - The system agent (cwd = the workspace repo itself, full permission
// bypass, NONE of the project-agent confinement) edits the harness's own
// building blocks: orchestrators, the design library, skills, MCP wiring.
// Earlier (v3.12) each System-tab section carried a persistent "Agent
// threads" panel with an always-on warning. That was loud. v3.13 redesigns:
//   • the warning + intake live INSIDE an "Add orchestrator" / "Add library
//     entry" flow, surfaced only when the user opts in,
//   • the intake gathers structure (what · how it's triggered · whether it
//     needs new library) and a visual of the orchestrator pipeline, then
//     composes a brief and hands it to a system thread,
//   • running / recent threads are reachable from ONE shared Bot icon button
//     in the landing title row - shared across Orchestrators + Design library.
// The run/persistence plumbing (scope:"system", /__system_runs,
// .system-chats/<section>.jsonl) is unchanged from v3.12; the spawn + drawer
// now live at ProjectsLanding so the header button can reach them.

function systemThreadStatus(r) {
  if (!r) return "done";
  if (!r.done && !r.historical) return r.turnDone ? "waiting" : "live";
  if (r.stopReason === "user-stop") return "stopped";
  return (r.exitCode === 0 || r.exitCode == null) ? "done" : "failed";
}
function fmtSystemThreadWhen(t) {
  if (!t) return "";
  try {
    const d = new Date(t * 1000);
    const sameDay = d.toDateString() === new Date().toDateString();
    return sameDay
      ? d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
      : d.toLocaleDateString([], { month: "short", day: "numeric" }) +
        " " + d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  } catch { return ""; }
}

const SYSTEM_THREAD_WARNING = html`
  <div className="sysadd-warning">
    <span className="sysadd-warning-icon">⚠</span>
    <span>
      This runs a <strong>workspace system agent</strong> with elevated access - cwd is the
      harness repo itself, permissions are bypassed, and the usual app-skill / orchestrator
      confinement is off, because its job is to edit those layers. Best for focused additions
      and updates. For sweeping refactors prefer a dedicated harness (Claude Code in a terminal
      at the workspace root) - bigger context, reviewable diffs, no daemon mid-flight.
    </span>
  </div>`;

// Trigger points are POSITIONS on the main build pipeline (see
// OrchestratorPipelineDiagram). `hook` maps a selected trigger to the stage
// it slots into so the diagram can light it up - answering the user's
// framing: "the pipeline is where it is triggered."
const ORCH_TRIGGER_OPTIONS = [
  { id: "upfront",   hook: "discuss",  label: "Upfront - with the main agent",
    desc: "fires during the opening discussion, before any source is scaffolded - the orchestrator can own the whole build (experience families: simulation / game / narrative / motion-studio brainstorm)" },
  { id: "on-source", hook: "scaffold", label: "After source is scaffolded",
    desc: "fires on the post-scaffold enumeration pass over the written HTML, like visual-orchestrator" },
  { id: "late",      hook: "polish",   label: "Late - after assets, before QA",
    desc: "fires near the end of the build, e.g. interactive-polish right before Step-8 QA" },
  { id: "manual",    hook: null,       label: "Manual / by name only",
    desc: "no automatic hook; only when the user or another agent invokes it explicitly" },
];
const LIBRARY_GROUPS = [
  { id: "shell",     label: "Shells" },
  { id: "style",     label: "Styles" },
  { id: "aesthetic", label: "Aesthetics" },
  { id: "recipe",    label: "Recipes" },
  { id: "photo",     label: "Photography" },
  { id: "illust",    label: "Illustration" },
  { id: "shader",    label: "Shaders" },
  { id: "material",  label: "Materials" },
  { id: "motion",    label: "Motion" },
];

// Each library GROUP (prefix) is read by exactly one consumer: the four build
// genres by the /prototype skill, the asset families by their orchestrator.
// This is the coupling that makes "what reads this entry" answerable from the
// group alone, and "new group = new structure" the orchestrator's concern.
const LIBRARY_GROUP_CONSUMER = {
  shell: "the /prototype skill", style: "the /prototype skill",
  aesthetic: "the /prototype skill", recipe: "the /prototype skill",
  photo: "photography-orchestrator", illust: "illustration-orchestrator",
  shader: "shader-orchestrator",
  material: "material-orchestrator", motion: "motion-studio-orchestrator",
};
function libraryConsumersFor(groupIds) {
  const out = [];
  for (const g of groupIds) { const c = LIBRARY_GROUP_CONSUMER[g]; if (c && !out.includes(c)) out.push(c); }
  return out;
}

function slugifyOrchestratorId(name) {
  let s = (name || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  if (!s) return "";
  if (!/orchestrator$/.test(s)) s = s.replace(/-?$/, "") + "-orchestrator";
  return s;
}

// The MAIN BUILD PIPELINE - a request flows left→right through the main
// agent's lifecycle, and an orchestrator hooks in at ONE of these points.
// The `selected` trigger set lights up where THIS orchestrator will fire, so
// the trigger question reads as "where on the pipeline is it triggered."
// (Not a diagram of an orchestrator's own internals - wrong altitude here.)
function OrchestratorPipelineDiagram({ selected }) {
  const hooks = new Set(
    ORCH_TRIGGER_OPTIONS.filter(o => selected && selected.has(o.id) && o.hook).map(o => o.hook)
  );
  const stages = [
    { id: "brief",    icon: Icon.Comment,  title: "Brief",       sub: "the user's ask" },
    { id: "discuss",  icon: Icon.Bot,      title: "Discuss",     sub: "main agent commits direction" },
    { id: "scaffold", icon: Icon.NotesDoc, title: "Scaffold",    sub: "main agent writes source" },
    { id: "assets",   icon: Icon.Image,    title: "Assets",      sub: "enumerate + fill slots" },
    { id: "polish",   icon: Icon.Spark,    title: "Polish + QA", sub: "interactions · checks" },
  ];
  return html`
    <div className="opipe" aria-label="Main build pipeline - orchestrator trigger points">
      ${stages.map((s, i) => html`
        <${React.Fragment} key=${s.id}>
          <div className=${"opipe-stage" + (hooks.has(s.id) ? " is-hook" : "")}>
            ${hooks.has(s.id) && html`<div className="opipe-hook">▸ triggers here</div>`}
            <div className="opipe-stage-icon"><${s.icon}/></div>
            <div className="opipe-stage-title">${s.title}</div>
            <div className="opipe-stage-sub">${s.sub}</div>
          </div>
          ${i < stages.length - 1 && html`<div className="opipe-arrow" aria-hidden="true">→</div>`}
        <//>
      `)}
    </div>
  `;
}

// Small reusable chip-toggle row.
function ChipToggleRow({ options, selected, onToggle, getId = (o) => o.id, getLabel = (o) => o.label }) {
  return html`
    <div className="sysadd-chiprow">
      ${options.map(o => {
        const id = getId(o);
        const on = selected.has(id);
        return html`
          <button key=${id} type="button"
            className=${"sysadd-chip" + (on ? " is-on" : "")}
            onClick=${() => onToggle(id)}
            title=${o.desc || ""}
          >${getLabel(o)}</button>
        `;
      })}
    </div>
  `;
}

// ── Add-orchestrator intake modal ──
function AddOrchestratorModal({ onClose, onSubmit }) {
  const [name, setName]         = useState("");
  const [desc, setDesc]         = useState("");
  const [triggers, setTriggers] = useState(() => new Set(["on-source"]));
  const [trigOther, setTrigOther] = useState("");
  const [needsGroup, setNeedsGroup] = useState("no");      // "no" | "yes" - a new orchestrator may define NEW library GROUP(s) = new structure
  const [newGroups, setNewGroups]   = useState([""]);      // names of the new group(s) it owns; can be multiple
  const [busy, setBusy]         = useState(false);
  const [err, setErr]           = useState(null);

  const proposedId = slugifyOrchestratorId(name);
  const canSubmit = name.trim() && desc.trim() && !busy;

  const toggle = (set, setter) => (id) => {
    const next = new Set(set);
    next.has(id) ? next.delete(id) : next.add(id);
    setter(next);
  };

  const compose = () => {
    const trigLabels = ORCH_TRIGGER_OPTIONS.filter(o => triggers.has(o.id))
      .map(o => `- ${o.label} - ${o.desc}`);
    if (trigOther.trim()) trigLabels.push(`- Other: ${trigOther.trim()}`);
    const groupNames = newGroups.map(g => g.trim()).filter(Boolean);
    const libLine = (needsGroup === "yes" && groupNames.length)
      ? "YES - defines new library group(s) (new STRUCTURE it owns + reads):\n" + groupNames.map(g => `  - ${g}`).join("\n")
      : "No new library group - it reads existing groups (or needs no library).";
    return `Add a NEW orchestrator to the workspace.

**Name:** ${name.trim()}
**Proposed id:** ${proposedId || "(you decide a kebab id ending in -orchestrator)"}

**What it should do:**
${desc.trim()}

**How it should be triggered:**
${trigLabels.join("\n") || "- (decide the appropriate trigger)"}

**New library group(s) (structure) needed:**
${libLine}

Scaffold it end-to-end following the workspace conventions you already know:
1. Write \`.claude/agents/${proposedId || "<id>"}.md\` (the playbook: \`name\` / \`description\` / \`tools\` frontmatter, then full operating instructions) and \`.claude/agents/${proposedId || "<id>"}.manifest.json\` (the registry entry the daemon + landing page read). If this orchestrator should gate project spawns, include a \`hardRule\` { header, body } field in the manifest so the capabilities preamble injects it dynamically (no capabilities.py edit needed).
2. If it defines new library group(s): each is NEW STRUCTURE (a category the orchestrator owns), not just entries in an existing group. For EACH new group, pick a kebab \`<prefix>\`, scaffold a few seed entries at \`design-library/<prefix>-<slug>.md\` (use an existing family like photo-* / material-* as the shape template), add a \`docs/research/<prefix>-library.md\` index if the family warrants one (mirroring photography-library.md / material-library.md), and wire the playbook to read that group. Existing library groups are read as-is - no new files.
3. Run the validation loop: \`curl $TH_DAEMON_URL/__orchestrators\` (your manifest parses + registers) and \`curl $TH_DAEMON_URL/__capabilities\` (it shows up). Report exactly what you created.

Restate your file plan in one short message; if anything is genuinely ambiguous, ask - otherwise proceed and report.`;
  };

  const submit = async () => {
    if (!canSubmit) return;
    setBusy(true); setErr(null);
    try {
      const title = `New orchestrator: ${name.trim().slice(0, 48)}`;
      await onSubmit({ section: "orchestrators", prompt: compose(), title });
      onClose();
    } catch (e) {
      setErr(e.message || String(e));
      setBusy(false);
    }
  };

  return createPortal(html`
    <div className="sysadd-overlay" onMouseDown=${(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="sysadd-card sysadd-card-wide" role="dialog" aria-modal="true" aria-label="Add orchestrator">
        <div className="sysadd-head">
          <h2>Add an orchestrator</h2>
          <button className="sysadd-close" onClick=${onClose} aria-label="Close"><${Icon.X}/></button>
        </div>
        <div className="sysadd-body">
          ${SYSTEM_THREAD_WARNING}

          <label className="sysadd-field">
            <span className="sysadd-label">Name</span>
            <input className="sysadd-input" value=${name} onInput=${e => setName(e.target.value)}
              placeholder="e.g. Diagram, Typography, Data-viz" autoFocus=${true}/>
            ${name.trim() && html`<span className="sysadd-hint">id: <code>${proposedId}</code> · playbook <code>.claude/agents/${proposedId}.md</code> + manifest</span>`}
          </label>

          <label className="sysadd-field">
            <span className="sysadd-label">What should it do?</span>
            <textarea className="sysadd-textarea" rows="4" value=${desc} onInput=${e => setDesc(e.target.value)}
              placeholder="What kind of artefact does it own, what drawers/lenses does it dispatch, what's the success bar?"></textarea>
          </label>

          <div className="sysadd-field">
            <span className="sysadd-label">Where in the build pipeline does it trigger?</span>
            <div className="sysadd-pipeline-wrap">
              <div className="sysadd-pipeline-caption">A request flows left → right through the main agent. Pick where your orchestrator hooks in - it lights up here.</div>
              <${OrchestratorPipelineDiagram} selected=${triggers}/>
            </div>
            <${ChipToggleRow} options=${ORCH_TRIGGER_OPTIONS} selected=${triggers} onToggle=${toggle(triggers, setTriggers)}/>
            <input className="sysadd-input sysadd-input-sub" value=${trigOther} onInput=${e => setTrigOther(e.target.value)}
              placeholder="…or describe the trigger condition in your own words (optional)"/>
          </div>

          <div className="sysadd-field">
            <span className="sysadd-label">Does it need a new library group?</span>
            <span className="sysadd-hint">A library group is a whole CATEGORY of design vocabulary an orchestrator owns + reads - photography-orchestrator owns <code>photo-</code>, material-orchestrator owns <code>material-</code>. Leave off if it reads existing groups (shell · style · aesthetic · recipe · photo · illust · shader · material · motion).</span>
            <div className="sysadd-radio-row">
              <button type="button" className=${"sysadd-radio" + (needsGroup === "no" ? " is-on" : "")} onClick=${() => setNeedsGroup("no")}>No - reads existing groups</button>
              <button type="button" className=${"sysadd-radio" + (needsGroup === "yes" ? " is-on" : "")} onClick=${() => setNeedsGroup("yes")}>Yes - define new group(s)</button>
            </div>
            ${needsGroup === "yes" && html`
              <div className="sysadd-sublib">
                ${newGroups.map((g, i) => html`
                  <div key=${i} className="sysadd-grouprow">
                    <input className="sysadd-input sysadd-input-sub" value=${g}
                      onInput=${e => { const v = e.target.value; setNewGroups(arr => arr.map((x, j) => j === i ? v : x)); }}
                      placeholder='New group - e.g. "diagram - flowchart / sequence / ER styles"'/>
                    ${newGroups.length > 1 && html`<button type="button" className="sysadd-grouprow-x" onClick=${() => setNewGroups(arr => arr.filter((_, j) => j !== i))} aria-label="Remove group"><${Icon.X}/></button>`}
                  </div>
                `)}
                <button type="button" className="sysadd-addgroup" onClick=${() => setNewGroups(arr => [...arr, ""])}><${Icon.Plus}/> Add another group</button>
              </div>
            `}
          </div>

          ${err && html`<div className="sysadd-error">${err}</div>`}
        </div>
        <div className="sysadd-foot">
          <span className="sysadd-foot-note">On create, this is handed to a system agent thread - you'll review its plan and steer there.</span>
          <div className="sysadd-foot-actions">
            <button className="sysadd-btn-cancel" onClick=${onClose} disabled=${busy}>Cancel</button>
            <button className="sysadd-btn-go" onClick=${submit} disabled=${!canSubmit}>${busy ? "Starting…" : "Create in a thread"}</button>
          </div>
        </div>
      </div>
    </div>
  `, document.body);
}

// ── Add / update design-library entry intake modal (lighter) ──
function AddLibraryModal({ onClose, onSubmit }) {
  const [desc, setDesc]     = useState("");
  const [groups, setGroups] = useState(() => new Set());
  const [busy, setBusy]     = useState(false);
  const [err, setErr]       = useState(null);

  const canSubmit = desc.trim() && !busy;
  const toggleGroup = (id) => {
    const next = new Set(groups);
    next.has(id) ? next.delete(id) : next.add(id);
    setGroups(next);
  };

  const compose = () => {
    const grpLine = [...groups].map(g => (LIBRARY_GROUPS.find(x => x.id === g) || {}).label || g).join(", ") || "(decide which group fits)";
    const consumers = libraryConsumersFor([...groups]);
    const readBy = consumers.length ? consumers.join(", ") : "the group's consumer (an orchestrator family, or the /prototype skill for shell / style / aesthetic / recipe)";
    return `Add or update design-library ENTRIES inside an existing group.

**Target group(s):** ${grpLine}
**Read by:** ${readBy}

**What to add / change:**
${desc.trim()}

This is an ENTRY change inside an existing group - NOT a new group (a new group is new structure, which is a new-orchestrator task). The group's consumer already reads the whole group, so:
1. Create or edit \`design-library/<prefix>-<slug>.md\` (YAML frontmatter + prose + any sample-image references), using the existing entries in that group as the shape template.
2. If the group has a discovery index (e.g. \`docs/research/<group>-library.index.json\` / \`.md\` for photo / illust / shader / material / motion), add or update your entry there too so the consumer can find it. Grep \`.claude/agents/\` and \`prototype/\` for references to any slug you rename or remove and fix them in the SAME change.
3. Verify with \`curl $TH_DAEMON_URL/__prototype_catalog\` and report what changed.

Restate your plan briefly; if anything is ambiguous, ask - otherwise proceed and report.`;
  };

  const submit = async () => {
    if (!canSubmit) return;
    setBusy(true); setErr(null);
    try {
      const title = `Library update: ${desc.trim().slice(0, 44)}`;
      await onSubmit({ section: "design-library", prompt: compose(), title });
      onClose();
    } catch (e) {
      setErr(e.message || String(e));
      setBusy(false);
    }
  };

  return createPortal(html`
    <div className="sysadd-overlay" onMouseDown=${(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="sysadd-card" role="dialog" aria-modal="true" aria-label="Add library entry">
        <div className="sysadd-head">
          <h2>Add / update a library entry</h2>
          <button className="sysadd-close" onClick=${onClose} aria-label="Close"><${Icon.X}/></button>
        </div>
        <div className="sysadd-body">
          ${SYSTEM_THREAD_WARNING}
          <div className="sysadd-field">
            <span className="sysadd-label">Which group?</span>
            <${ChipToggleRow} options=${LIBRARY_GROUPS} selected=${groups} onToggle=${toggleGroup}/>
          </div>
          <label className="sysadd-field">
            <span className="sysadd-label">What to add or change?</span>
            <textarea className="sysadd-textarea" rows="4" value=${desc} onInput=${e => setDesc(e.target.value)}
              placeholder="Describe the entry (or the edit). The agent reads existing entries in that group as the template."></textarea>
          </label>
          <div className="sysadd-field">
            <span className="sysadd-label">Read by</span>
            ${groups.size === 0
              ? html`<span className="sysadd-hint">Pick a group above - its consumer (the orchestrator or /prototype skill that reads it) shows here. Need a brand-new category instead? That's a new library group - start it from "Add orchestrator".</span>`
              : html`<div className="sysadd-readby">${libraryConsumersFor([...groups]).map(c => html`<span key=${c} className="sysadd-readby-chip">${c}</span>`)}</div>`}
          </div>
          ${err && html`<div className="sysadd-error">${err}</div>`}
        </div>
        <div className="sysadd-foot">
          <span className="sysadd-foot-note">Handed to a system agent thread - review + steer there.</span>
          <div className="sysadd-foot-actions">
            <button className="sysadd-btn-cancel" onClick=${onClose} disabled=${busy}>Cancel</button>
            <button className="sysadd-btn-go" onClick=${submit} disabled=${!canSubmit}>${busy ? "Starting…" : "Update in a thread"}</button>
          </div>
        </div>
      </div>
    </div>
  `, document.body);
}

// ── Standardized System-tab section header ──
// One shape for every System content pane: section name + count chip on the
// left, an optional primary action on the right, a one-line description below,
// and optional `extra` (filter-relevant prose / category list) beneath that.
function SystemSectionHead({ name, count, desc, action, extra }) {
  // desc/extra arrive as htm template results - a multi-child template (text +
  // <code> + …) is a bare array, which preact flags for missing keys when
  // rendered directly. Key array children so the console stays clean.
  const keyed = (x) => Array.isArray(x)
    ? x.map((c, i) => (c && typeof c === "object" && c.key == null) ? { ...c, key: "k" + i } : c)
    : x;
  return html`
    <header className="sys-shead">
      <div className="sys-shead-row">
        <div className="sys-shead-titles">
          <span className="sys-shead-title">${name}</span>
          ${count != null && html`<span className="sys-shead-count">${count}</span>`}
        </div>
        ${action ? html`<div className="sys-shead-action">${action}</div>` : null}
      </div>
      ${desc && html`<div className="sys-shead-desc">${keyed(desc)}</div>`}
      ${keyed(extra) || null}
    </header>
  `;
}

// ── Per-section action bar - the normal "+ Add" button that opens intake ──
function SystemAddBar({ kind, onSpawn }) {
  const [open, setOpen] = useState(false);
  const label = kind === "orchestrators" ? "Add orchestrator" : "Add / update library entry";
  const Modal = kind === "orchestrators" ? AddOrchestratorModal : AddLibraryModal;
  return html`
    <${React.Fragment}>
      <button className="sysadd-bar-btn" onClick=${() => setOpen(true)}>
        <${Icon.Plus}/><span>${label}</span>
      </button>
      ${open && html`<${Modal} onClose=${() => setOpen(false)} onSubmit=${onSpawn}/>`}
    <//>
  `;
}

// ── Shared Bot icon button in the landing title row → thread dropdown ──
function SystemAgentThreadButton({ threads, onOpen }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);
  const live = threads.filter(t => { const s = systemThreadStatus(t); return s === "live" || s === "waiting"; }).length;
  return html`
    <div className="landing-threads" ref=${ref}>
      <button className=${"landing-threads-btn" + (live > 0 ? " has-live" : "")} onClick=${() => setOpen(o => !o)}
        title="Workspace system-agent threads" aria-expanded=${open}>
        <${Icon.Bot}/>
        <span className="landing-threads-count">${threads.length}</span>
      </button>
      ${open && html`
        <div className="landing-threads-menu">
          <div className="landing-threads-menu-head">System agent threads</div>
          ${threads.map(r => html`
            <button key=${r.runId} className="landing-threads-row" onClick=${() => { onOpen(r); setOpen(false); }}>
              <span className=${"system-threads-dot is-" + systemThreadStatus(r)}></span>
              <span className="landing-threads-row-main">
                <span className="landing-threads-row-title">${r.title || r.runId}</span>
                <span className="landing-threads-row-meta">${r.section || "system"} · ${systemThreadStatus(r)} · ${fmtSystemThreadWhen(r.startedAt)}</span>
              </span>
            </button>
          `)}
        </div>
      `}
    </div>
  `;
}


function SystemLanding({ onSpawnSystemThread }) {
  const [activeSection, setActiveSection] = useState("default-library");

  // Live counts for the sidebar - hydrate from /__capabilities (cheap GET).
  const [caps, setCaps]         = useState(null);
  const [orchestratorsData, setOrchestratorsData] = useState(null);
  // v3.6 - design library catalog. Cheap GET; the daemon walks
  // INSTALL_ROOT/design-library/ each call so newly-dropped sample images
  // and edited frontmatter show up without restarting the server. (Endpoint
  // name `/__prototype_catalog` is kept for compatibility - the catalog
  // sources from design-library/, not from the prototype/ skill-detail folder.)
  const [protoCatalog, setProtoCatalog] = useState(null);
  const [mcpCatalog, setMcpCatalog] = useState(null);
  const [globalFonts, setGlobalFonts] = useState(null);
  useEffect(() => {
    fetch(apiUrl("/__capabilities")).then(r => r.ok ? r.json() : null).then(setCaps).catch(() => {});
    fetch(apiUrl("/__orchestrators")).then(r => r.ok ? r.json() : null).then(setOrchestratorsData).catch(() => {});
    fetch(apiUrl("/__prototype_catalog")).then(r => r.ok ? r.json() : null).then(setProtoCatalog).catch(() => {});
    fetch(apiUrl("/__mcp_catalog")).then(r => r.ok ? r.json() : null).then(setMcpCatalog).catch(() => {});
    fetch(apiUrl("/__fonts?scope=global")).then(r => r.ok ? r.json() : null).then(setGlobalFonts).catch(() => {});
  }, []);
  // Keep the "Custom fonts" sidebar count live while the panel uploads/removes.
  useEffect(() => {
    const refetch = () => fetch(apiUrl("/__fonts?scope=global")).then(r => r.ok ? r.json() : null).then(setGlobalFonts).catch(() => {});
    window.addEventListener("th:fonts-changed", refetch);
    return () => window.removeEventListener("th:fonts-changed", refetch);
  }, []);
  // v3.12 - a system agent thread modified the harness (orchestrators /
  // library / skills / MCP). Re-pull every registry this tab renders.
  useEffect(() => {
    const refetch = () => {
      fetch(apiUrl("/__capabilities")).then(r => r.ok ? r.json() : null).then(setCaps).catch(() => {});
      fetch(apiUrl("/__orchestrators")).then(r => r.ok ? r.json() : null).then(setOrchestratorsData).catch(() => {});
      fetch(apiUrl("/__prototype_catalog")).then(r => r.ok ? r.json() : null).then(setProtoCatalog).catch(() => {});
      fetch(apiUrl("/__mcp_catalog")).then(r => r.ok ? r.json() : null).then(setMcpCatalog).catch(() => {});
    };
    window.addEventListener("th:system-changed", refetch);
    return () => window.removeEventListener("th:system-changed", refetch);
  }, []);
  const skills = (window.TH_MEDIA && window.TH_MEDIA.skills) || [];

  const sections = [
    { id: "default-library", label: "Template Design System", count: null,
      hint: "The bundled template design system - curated retunes previewed on two surfaces + try customisation live" },
    { id: "prototype",  label: "Design library", count: protoCatalog ? protoCatalog.total : 548,
      hint: "Shells · styles · aesthetics · recipes · photography · illustration · materials - the design-library/ visual catalog" },
    { id: "orchestrators",   label: "Orchestrators",   count: orchestratorsData ? orchestratorsData.count : 3,
      hint: "Orchestrators that dispatch families of subagents" },
    { id: "fonts",      label: "Custom fonts",   count: globalFonts ? globalFonts.count : 0,
      hint: "Your uploaded font collection - shared across every project; agents check these first when proposing typography" },
    { id: "skills",     label: "Skills",     count: skills.length,
      hint: "Generators - Pathway A (vendor API) or B (Claude writes file)" },
    { id: "subagents",  label: "Subagents",  count: caps ? caps.subagents.length : 63,
      hint: "Every .claude/agents/*.md - drawers, lenses, orchestrators, cross-cutting" },
    { id: "node-kinds", label: "Node kinds", count: caps ? caps.kinds.length : 21,
      hint: "Canvas node types - what each does + how to use it" },
    { id: "mcp",        label: "MCP servers", count: mcpCatalog ? (mcpCatalog.servers || []).length : 2,
      hint: "Optional MCP servers wired into spawned claude subprocesses - escalation paths beyond built-in WebFetch / WebSearch" },
  ];

  return html`
    <div className="system-landing">
      <nav className="system-sidebar" aria-label="System sections">
        <div className="system-sidebar-header">Capabilities</div>
        <div className="system-sidebar-subhead">What this app can do, what's available to dispatch, and what each piece is for.</div>
        ${sections.map(s => html`
          <button
            key=${s.id}
            className=${"system-nav-item" + (activeSection === s.id ? " is-active" : "")}
            onClick=${() => setActiveSection(s.id)}
            aria-pressed=${activeSection === s.id}
            title=${s.hint}
          >
            <span className="system-nav-label">${s.label}</span>
            ${s.count != null && html`<span className="system-nav-count">${s.count}</span>`}
            <span className="system-nav-hint">${s.hint}</span>
          </button>
        `)}
      </nav>
      <div className="system-content">
        ${activeSection === "default-library" && html`<${DefaultLibraryLanding}/>`}
        ${activeSection === "orchestrators"   && html`<${OrchestratorsLanding} scopeLabel="workspace" onSpawnSystemThread=${onSpawnSystemThread}/>`}
        ${activeSection === "skills"     && html`<${SkillsLanding}/>`}
        ${activeSection === "fonts"      && html`<div className="system-fonts"><${DSFontsPanel} scope="global"/></div>`}
        ${activeSection === "prototype"  && html`<${PrototypeCatalogLanding} data=${protoCatalog} onSpawnSystemThread=${onSpawnSystemThread}/>`}
        ${activeSection === "subagents"  && html`<${SubagentsLanding} caps=${caps}/>`}
        ${activeSection === "node-kinds" && html`<${NodeKindsLanding} caps=${caps}/>`}
        ${activeSection === "mcp"        && html`<${McpLanding}/>`}
      </div>
    </div>
  `;
}


// ─── SkillsLanding ────────────────────────────────────────────────────────
// v3.3 - Skills inventory. Pulls from window.TH_MEDIA.skills (the canonical
// SKILLS array in editor/prompts/media-models.js) PLUS harness-local skills
// surfaced via /__cc_skills. The harness deliberately DOES NOT read the
// user's global ~/.claude/ install - agents spawned by the harness don't
// get access to the user's Claude Code skill library, so any skill the
// agent should be able to invoke has to be added to this harness here.
// Each card is collapsible - head click expands; body hidden by default
// so scanning the full set doesn't require a long scroll.
function SkillsLanding() {
  const skills = (window.TH_MEDIA && window.TH_MEDIA.skills) || [];
  const imageModels = (window.TH_MEDIA && window.TH_MEDIA.imageModels) || [];
  const textModels  = (window.TH_MEDIA && window.TH_MEDIA.textModels) || [];
  const videoModels = (window.TH_MEDIA && window.TH_MEDIA.videoModels) || [];
  const models3d    = (window.TH_MEDIA && window.TH_MEDIA.models3d) || [];
  const allModels = [...imageModels, ...textModels, ...videoModels, ...models3d];

  // Harness-local skills: fetched from daemon on mount. The daemon walks
  // the workspace-scoped <workspace>/.harness-skills/ dir (or install-root
  // fallback) and returns {name, description, source, slug, path} for
  // each SKILL.md. Nothing from the user's global ~/.claude/ install
  // is read or invokable.
  const [ccSkills, setCcSkills] = useState(null);    // null = loading, [] = none
  const [ccError, setCcError]   = useState(null);
  const [ccRoot, setCcRoot]     = useState(null);
  const [uploadBusy, setUploadBusy] = useState(false);
  const [uploadMsg, setUploadMsg]   = useState(null);
  const uploadInputRef = useRef(null);

  const loadCcSkills = useCallback(async () => {
    try {
      const r = await fetch(apiUrl("/__cc_skills"));
      if (!r.ok) {
        // Older daemons without the endpoint return 404 - fall through silently.
        setCcSkills([]);
        return;
      }
      const j = await r.json();
      setCcSkills(j.skills || []);
      setCcRoot(j.root || null);
    } catch (e) {
      setCcError(e.message || String(e));
      setCcSkills([]);
    }
  }, []);
  useEffect(() => { loadCcSkills(); }, [loadCcSkills]);
  // v3.13 - refresh when a system-agent thread installs/edits a harness skill.
  useEffect(() => {
    window.addEventListener("th:system-changed", loadCcSkills);
    return () => window.removeEventListener("th:system-changed", loadCcSkills);
  }, [loadCcSkills]);

  const onUpload = useCallback(async (files) => {
    if (!files || !files.length) return;
    setUploadBusy(true); setUploadMsg(null);
    try {
      const fd = new FormData();
      for (let i = 0; i < files.length; i++) {
        fd.append(`file${i}`, files[i], files[i].name);
      }
      const r = await fetch(apiUrl("/__cc_skills/upload"), { method: "POST", body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
      setUploadMsg(`Installed ${j.installed || files.length} skill(s).`);
      await loadCcSkills();
    } catch (e) {
      setUploadMsg("Upload failed: " + (e.message || e));
    } finally {
      setUploadBusy(false);
    }
  }, [loadCcSkills]);

  // Group media skills by pathway.
  const groups = {
    "A": { label: "Pathway A - vendor API call", desc: "Daemon POSTs to a provider (OpenAI / fal.ai / Anthropic / etc.) and receives bytes back. Requires the provider's API key in Settings.", items: [] },
    "B": { label: "Pathway B - Claude writes the file", desc: "Spawns a Claude Code subprocess with a curated system prompt. The agent writes one self-contained file (HTML / SVG / JSON) per Run. No external API key beyond Claude.", items: [] },
    "Tool": { label: "Pathway Tool - interactive editor", desc: "Drops a fixed, self-contained interactive HTML tool into the project (no agent, no API key). The node renders the live tool in its iframe - e.g. the Spline-style 3D editor.", items: [] },
    "Local": { label: "Pathway Local - local binary", desc: "Runs a Python package installed via pip (e.g. rembg) on the daemon machine. No network call, no API key.", items: [] },
  };
  for (const sk of skills) {
    const p = sk.pathway || "B";
    if (groups[p]) groups[p].items.push(sk);
  }

  // Harness-local skills. Single group - there's no notion of
  // "plugin-bundled" here because the harness deliberately ignores the
  // user's global Claude Code install.
  const ccList = Array.isArray(ccSkills) ? ccSkills : [];

  const totalCount = skills.length + ccList.length;

  return html`
    <div className="ref-root">
      <input
        ref=${uploadInputRef}
        type="file"
        accept=".md,.zip,.json"
        multiple
        style=${{ display: "none" }}
        onChange=${(e) => {
          const fs = Array.from(e.target.files || []);
          if (fs.length) onUpload(fs);
          e.target.value = "";
        }}
      />
      <${SystemSectionHead}
        name="Skills"
        count=${totalCount}
        desc=${html`A skill is a unit of generation. Media skills run on the canvas; custom skills you add to this harness are invokable via <code>${"/<skill-name>"}</code> in the chat composer. Drop a <code>SKILL.md</code> (or a <code>.zip</code> containing one) anywhere on this panel to install one <strong>for this harness only</strong>.`}
        action=${html`<button className="sysadd-bar-btn" type="button" disabled=${uploadBusy}
          onClick=${() => uploadInputRef.current && uploadInputRef.current.click()}
          title="Upload a SKILL.md (or .zip) - installed to this harness only">
          <${Icon.Plus}/><span>${uploadBusy ? "Uploading…" : "Add skill"}</span></button>`}
        extra=${(uploadMsg || ccError || ccRoot) && html`<div className="sys-shead-extra">
          ${ccRoot && html`<span>Installed under <code>${ccRoot}</code></span>`}
          ${uploadMsg && html`<div className="skills-upload-msg">${uploadMsg}</div>`}
          ${ccError && html`<div className="skills-upload-msg skills-upload-msg-err">Skills load error: ${ccError}</div>`}
        </div>`}
      />

      ${ccList.length > 0 && html`
        <div className="ref-group ref-group-user">
          <div className="ref-group-head">
            <div className="ref-group-title">Custom skills <span className="ref-group-count">${ccList.length}</span></div>
            <div className="ref-group-desc">Skills you've added to this harness. Invokable in the chat composer with <code>/name</code>. Stored locally - not synced to your global Claude Code install.</div>
          </div>
          <div className="ref-grid">
            ${ccList.map(sk => html`<${CcSkillCard} key=${sk.slug} skill=${sk} reload=${loadCcSkills}/>`)}
          </div>
        </div>
      `}

      ${Object.entries(groups).map(([key, g]) => g.items.length === 0 ? null : html`
        <div key=${key} className="ref-group">
          <div className="ref-group-head">
            <div className="ref-group-title">${g.label} <span className="ref-group-count">${g.items.length}</span></div>
            <div className="ref-group-desc">${g.desc}</div>
          </div>
          <div className="ref-grid">
            ${g.items.map(sk => html`<${MediaSkillCard} key=${sk.id} skill=${sk} allModels=${allModels}/>`)}
          </div>
        </div>
      `)}
    </div>
  `;
}

// Media-generation skill card (from TH_MEDIA.skills). Collapsible - head
// click toggles the body. Default collapsed so the grid is scannable.
function MediaSkillCard({ skill: sk, allModels }) {
  const [open, setOpen] = useState(false);
  const [promptOpen, setPromptOpen] = useState(false);
  return html`
    <div className=${"skill-card" + (open ? " is-expanded" : " is-collapsed")} data-pathway=${sk.pathway}>
      <div
        className="skill-card-head"
        onClick=${() => setOpen(x => !x)}
        title=${open ? "Click to collapse" : "Click to expand"}
        style=${{ cursor: "pointer" }}
      >
        <span className="skill-card-disclosure" aria-hidden="true">${open ? "▼" : "▶"}</span>
        <span className="skill-glyph">${skillGlyph(sk)}</span>
        <div className="skill-card-head-text">
          <div className="skill-card-name">
            <span className="skill-label">${sk.label}</span>
            <code className="skill-id">${sk.id}</code>
          </div>
          <div className="skill-card-hint">${sk.hint}</div>
        </div>
        <span className=${"skill-pathway skill-pathway-" + sk.pathway}>${sk.pathway}</span>
      </div>

      ${open && html`
      <div className="skill-section">
        <div className="skill-row">
          <span className="skill-row-label">Inputs</span>
          <div className="skill-chip-row">
            ${(sk.inputs || []).map(i => html`<code key=${i} className="skill-chip skill-chip-input">${i}</code>`)}
          </div>
        </div>
        <div className="skill-row">
          <span className="skill-row-label">Output</span>
          <code className=${"skill-chip skill-chip-output skill-chip-output-" + sk.output}>${sk.output}</code>
        </div>
        ${sk.hasAspect && html`
          <div className="skill-row">
            <span className="skill-row-label">Aspect</span>
            <span className="skill-row-value">configurable per Run</span>
          </div>
        `}
        ${sk.defaultModel && html`
          <div className="skill-row">
            <span className="skill-row-label">Default model</span>
            <code className="skill-chip skill-chip-model">${sk.defaultModel}</code>
            ${(() => {
              const m = allModels.find(mm => mm.id === sk.defaultModel);
              return m ? html`<span className="skill-row-value-meta">${m.label} · ${m.provider}</span>` : null;
            })()}
          </div>
        `}
        ${sk.pathwayBExt && html`
          <div className="skill-row">
            <span className="skill-row-label">Output file</span>
            <code className="skill-chip skill-chip-ext">.${sk.pathwayBExt}</code>
          </div>
        `}
      </div>

      ${sk.pathwayBSystem && html`
        <div className="skill-section">
          <button
            className="skill-expand-btn"
            onClick=${() => setPromptOpen(x => !x)}
            aria-expanded=${promptOpen ? "true" : "false"}
          >
            ${promptOpen ? "▼" : "▶"} System prompt (${sk.pathwayBSystem.length} chars)
          </button>
          ${promptOpen && html`<pre className="skill-system-prompt">${sk.pathwayBSystem}</pre>`}
        </div>
      `}

      <div className="skill-section skill-howto">
        <div className="skill-howto-label">How to use</div>
        <div className="skill-howto-body">
          Drop a Skill node on the canvas, set its <code>skill</code> to <code>${sk.id}</code>, wire a Prompt
          node into <code>.in</code>, wire <code>.out</code> to an Asset node. Click Run.
          ${sk.pathway === "A" && " The daemon posts to the provider; ensure the API key is set in Settings."}
          ${sk.pathway === "B" && " A Claude Code subprocess will spawn with the system prompt above; visible in the run panel."}
          ${sk.pathway === "Local" && " The daemon runs the local binary; no API key needed but the package must be pip-installed."}
        </div>
      </div>
      `}
    </div>
  `;
}

// Claude Code skill card. Smaller than the media skill card - these come
// from SKILL.md frontmatter (name + description only). Collapsible same
// pattern; expanded body shows the slash-command invocation + source path.
function CcSkillCard({ skill: sk, reload }) {
  const [open, setOpen] = useState(false);
  const [removing, setRemoving] = useState(false);

  const onRemove = async (e) => {
    e.stopPropagation();
    if (!(await uiConfirm(`Delete skill "${sk.name}" from ~/.claude/skills/${sk.slug}/?`))) return;
    setRemoving(true);
    try {
      const r = await fetch(apiUrl("/__cc_skills/delete"), {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({ slug: sk.slug }),
      });
      if (!r.ok) {
        const j = await r.json().catch(() => ({}));
        throw new Error(j.error || `HTTP ${r.status}`);
      }
      if (reload) await reload();
    } catch (err) {
      uiAlert("Delete failed: " + (err.message || err));
    } finally {
      setRemoving(false);
    }
  };

  const invocation = sk.invocation || ("/" + sk.slug);
  return html`
    <div className=${"skill-card cc-skill-card" + (open ? " is-expanded" : " is-collapsed")} data-source=${sk.source}>
      <div
        className="skill-card-head"
        onClick=${() => setOpen(x => !x)}
        title=${open ? "Click to collapse" : "Click to expand"}
        style=${{ cursor: "pointer" }}
      >
        <span className="skill-card-disclosure" aria-hidden="true">${open ? "▼" : "▶"}</span>
        <span className="skill-glyph">/</span>
        <div className="skill-card-head-text">
          <div className="skill-card-name">
            <span className="skill-label">${sk.name}</span>
            <code className="skill-id">${invocation}</code>
          </div>
          <div className="skill-card-hint">${sk.description || ""}</div>
        </div>
        <span className=${"skill-pathway skill-pathway-CC"}>custom</span>
      </div>

      ${open && html`
        <div className="skill-section">
          <div className="skill-row">
            <span className="skill-row-label">Invoke</span>
            <code className="skill-chip skill-chip-output">${invocation}</code>
            <span className="skill-row-value">in the chat composer (or via Skill tool)</span>
          </div>
          ${sk.path && html`
            <div className="skill-row">
              <span className="skill-row-label">Source</span>
              <code className="skill-chip skill-chip-ext">${sk.path}</code>
            </div>
          `}
          ${sk.source === "user" && html`
            <div className="skill-row">
              <button className="skill-remove-btn" onClick=${onRemove} disabled=${removing} title="Delete this skill directory">
                ${removing ? "Deleting…" : "Delete"}
              </button>
            </div>
          `}
        </div>
      `}
    </div>
  `;
}


// ─── PrototypeCatalogLanding ─────────────────────────────────────────────
// v3.6 - The PROTOTYPE.md-backed design library, rendered as a browsable catalog.
//
// What this surface is. Woven prototypes commit a "genre" - a shell + style +
// aesthetic + voice tuple - before any drawing happens (see PROTOTYPE.md
// §Step zero). The detail vocabulary for every choice lives one file per
// option under INSTALL_ROOT/design-library/. Until now those files were only
// readable when an agent loaded them mid-build; the user couldn't browse
// the menu. This component fixes that: the user opens the System tab,
// switches to "Design library", and scans every shell / style / aesthetic /
// recipe / photography / illustration / material the workspace ships with.
// (Skill-detail files - step-*, scene-addendum-details, gallery-html,
// demo-dock, raster-requirements, preflight-checklist, woven-repo-conventions,
// slot-annotations - live in INSTALL_ROOT/prototype/ NOT in design-library/;
// they describe HOW to draw, not WHAT, and are excluded from this catalog.)
//
// Sample images. Each genre can attach 0..N sample images via optional
// YAML frontmatter (`images: [{src, reason}, ...]`). The reason is the
// load-bearing field - it explains *what about the image* the genre is
// referencing (a hero composition, a palette, a type pairing, a motion
// register). When the user commits a direction the catalog images become
// the design references the project builds toward, since most Woven
// projects have no separate design system to point at.
//
// Non-determinism callout. The component renders an explicit reminder
// that picks aren't deterministic - a finished design often gradients
// between recipes or borrows one aesthetic's palette while wearing
// another shell. The note comes back from the daemon so chat-side
// agents and this UI agree on the wording.
function PrototypeCatalogLanding({ data, onSpawnSystemThread }) {
  // The active filter - "all" lists every group sequentially; selecting
  // one category shows only that group. Same chip pattern as
  // SubagentsLanding so the System tab stays consistent.
  const [filterKey, setFilterKey] = useState("all");
  const [query, setQuery] = useState("");
  // Per-card image overlay (lightbox). Holds {src, reason, title} when open.
  const [zoom, setZoom] = useState(null);
  // Progressive (infinite-scroll) render window. The catalog is ~500 cards
  // each carrying a full-res sample PNG; mounting them all at once is what made
  // this page heavy. Instead we mount the first BATCH and append the next BATCH
  // whenever the bottom sentinel scrolls into view, so the first screen paints
  // its images immediately and the rest stream in as the user scrolls.
  const BATCH = 24;
  const [renderLimit, setRenderLimit] = useState(BATCH);
  const sentinelRef = useRef(null);

  // NB: the `!data` early return lives below the hooks (after the effects), so
  // hook order stays stable across the loading → loaded transition. Everything
  // here is null-safe so it can compute before data lands.
  const groups = data && Array.isArray(data.groups) ? data.groups : [];
  const total  = (data && data.total) || 0;

  // Apply the text filter to every group's items (case-insensitive match
  // against title / slug / summary). Empty filter passes everything.
  const q = query.trim().toLowerCase();
  const filterItem = (it) => {
    if (!q) return true;
    return (it.title || "").toLowerCase().includes(q)
        || (it.slug  || "").toLowerCase().includes(q)
        || (it.summary || "").toLowerCase().includes(q);
  };
  const visibleGroups = (filterKey === "all" ? groups : groups.filter(g => g.key === filterKey))
    .map(g => ({ ...g, items: g.items.filter(filterItem) }))
    .filter(g => g.items.length > 0);
  const filteredTotal = visibleGroups.reduce((sum, g) => sum + g.items.length, 0);

  // Walk groups in order and only mount cards up to renderLimit. Each capped
  // group keeps its FULL count for the header badge while rendering a slice.
  let budget = renderLimit;
  const cappedGroups = [];
  for (const g of visibleGroups) {
    if (budget <= 0) break;
    const slice = g.items.slice(0, budget);
    budget -= slice.length;
    cappedGroups.push({ ...g, items: slice, fullCount: g.items.length });
  }
  const renderedCount = cappedGroups.reduce((sum, g) => sum + g.items.length, 0);
  const hasMore = renderedCount < filteredTotal;

  // Reset the window to the top whenever the filter or query changes, so a
  // narrowed result set doesn't inherit a deep scroll offset.
  useEffect(() => { setRenderLimit(BATCH); }, [filterKey, q]);

  // Append the next batch when the sentinel nears the viewport. rootMargin
  // pre-loads ~600px early so scrolling feels continuous, not stop-start. The
  // effect re-runs on renderedCount so the observer re-arms after each append.
  useEffect(() => {
    if (!hasMore) return;
    const el = sentinelRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver((entries) => {
      if (entries.some(e => e.isIntersecting)) setRenderLimit(l => l + BATCH);
    }, { rootMargin: "600px 0px" });
    io.observe(el);
    return () => io.disconnect();
  }, [hasMore, renderedCount]);

  if (!data) {
    return html`<div className="ref-loading">Loading design library…</div>`;
  }

  return html`
    <div className="ref-root">
      <${SystemSectionHead}
        name="Design library"
        count=${total}
        desc="The vocabulary every Woven prototype inherits from. Each category feeds a specific consumer:"
        action=${onSpawnSystemThread && html`<${SystemAddBar} kind="design-library" onSpawn=${onSpawnSystemThread}/>`}
        extra=${html`<ul className="ref-header-categories">
          <li><strong>Shells · Styles · Aesthetics · Recipes</strong> - read by the <code>/prototype</code> skill when a project commits a direction.</li>
          <li><strong>Photography</strong> - read by <code>photography-orchestrator</code> to art-direct raster-photo slots.</li>
          <li><strong>Illustration</strong> - read by <code>illustration-orchestrator</code> to art-direct raster-foreground slots.</li>
          <li><strong>Materials</strong> - read by <code>material-orchestrator</code> for the post-pass fidelity layer (glass, clay, chrome, holographic, paper grain, film grain, etc.).</li>
        </ul>`}
      />

      <div className="ref-filter-row">
        <button
          className=${"ref-filter-chip" + (filterKey === "all" ? " is-active" : "")}
          onClick=${() => setFilterKey("all")}
        >All <span className="ref-filter-count">${total}</span></button>
        ${groups.map(g => html`
          <button
            key=${g.key}
            className=${"ref-filter-chip" + (filterKey === g.key ? " is-active" : "")}
            onClick=${() => setFilterKey(g.key)}
            title=${g.description}
          >${g.label} <span className="ref-filter-count">${g.items.length}</span></button>
        `)}
        <input
          className="proto-catalog-search"
          placeholder="Filter by name or text…"
          value=${query}
          onInput=${e => setQuery(e.target.value)}
        />
      </div>

      ${q && html`<div className="proto-catalog-filter-result">Showing ${filteredTotal} of ${total} matching “${query}”.</div>`}

      ${visibleGroups.length === 0 && html`
        <div className="ref-empty">No detail files match the current filter.</div>
      `}

      ${cappedGroups.map(g => html`
        <div key=${g.key} className="ref-group proto-catalog-group" data-cat=${g.key}>
          <div className="ref-group-head">
            <div className="ref-group-title">${g.label} <span className="ref-group-count">${g.fullCount}</span></div>
            <div className="ref-group-desc">${g.description}</div>
          </div>
          <div className="proto-catalog-grid">
            ${g.items.map(it => html`<${PrototypeGenreCard}
              key=${it.slug}
              item=${it}
              category=${g.key}
              onZoom=${(img) => setZoom({ ...img, title: it.title })}
            />`)}
          </div>
        </div>
      `)}

      ${hasMore && html`
        <div ref=${sentinelRef} className="proto-catalog-sentinel" aria-hidden="true">
          <span className="proto-catalog-sentinel-spinner"></span>
          Loading more… ${renderedCount} of ${filteredTotal}
        </div>
      `}

      ${zoom && createPortal(html`
        <div className="proto-catalog-zoom" onClick=${() => setZoom(null)} role="dialog" aria-label="Image preview">
          <button
            className="proto-catalog-zoom-close"
            onClick=${(e) => { e.stopPropagation(); setZoom(null); }}
            aria-label="Close preview"
          >×</button>
          <figure className="proto-catalog-zoom-figure" onClick=${(e) => e.stopPropagation()}>
            <img className="proto-catalog-zoom-img" src=${apiUrl(zoom.src)} alt=${zoom.reason || zoom.title}/>
            <figcaption className="proto-catalog-zoom-caption">
              <strong>${zoom.title}</strong>
              ${zoom.reason && html`<span> - ${zoom.reason}</span>`}
            </figcaption>
          </figure>
        </div>
      `, document.body)}
    </div>
  `;
}

// One card per detail .md. Title + slug + short summary + image strip.
// Images are clickable to enlarge; reasons display under each image so
// the user understands *why* that reference belongs to this genre.
function PrototypeGenreCard({ item, category, onZoom }) {
  const [open, setOpen] = useState(false);
  const hasImages = item.images && item.images.length > 0;
  return html`
    <article className=${"proto-catalog-card" + (open ? " is-open" : "")} data-cat=${category}>
      <header
        className="proto-catalog-card-head"
        onClick=${() => setOpen(x => !x)}
        title=${open ? "Click to collapse" : "Click to expand"}
      >
        <span className="proto-catalog-card-disclosure" aria-hidden="true">${open ? "▼" : "▶"}</span>
        <div className="proto-catalog-card-titles">
          <div className="proto-catalog-card-title">${item.title}</div>
          <code className="proto-catalog-card-slug">${item.slug}</code>
        </div>
        <span className="proto-catalog-card-imgcount" title=${hasImages
          ? `${item.images.length} reference image${item.images.length === 1 ? "" : "s"} attached`
          : "No reference images yet - add via the file's frontmatter"}>
          ${hasImages ? `${item.images.length} ref${item.images.length === 1 ? "" : "s"}` : "no refs yet"}
        </span>
      </header>

      ${item.summary && html`
        <div className="proto-catalog-card-summary">${item.summary}</div>
      `}

      <div className="proto-catalog-card-imgstrip" data-empty=${!hasImages}>
        ${hasImages
          ? item.images.map((img, i) => html`
              <figure key=${i} className=${"proto-catalog-thumb" + (img.exists ? "" : " is-missing")}>
                <button
                  type="button"
                  className="proto-catalog-thumb-btn"
                  onClick=${() => img.exists && onZoom && onZoom(img)}
                  title=${img.exists
                    ? (img.reason || "Open full size")
                    : "Image file not on disk yet - add it to prototype/ to populate this reference"}
                  disabled=${!img.exists}
                >
                  ${img.exists
                    ? html`<img src=${apiUrl(img.src)} alt=${img.reason || item.title} loading="lazy" decoding="async"/>`
                    : html`<span className="proto-catalog-thumb-placeholder">placeholder</span>`}
                </button>
                ${img.reason && html`<figcaption className="proto-catalog-thumb-caption">${img.reason}</figcaption>`}
              </figure>
            `)
          : html`
              <div className="proto-catalog-thumb-empty">
                <span className="proto-catalog-thumb-empty-glyph" aria-hidden="true">▦</span>
                <span>No sample images yet. Drop a <code>${item.slug}-1.png</code> into
                <code>prototype/</code> and reference it in this file's frontmatter to use it as a
                project design reference.</span>
              </div>
            `}
      </div>

      ${open && html`
        <div className="proto-catalog-card-meta">
          <div className="proto-catalog-card-meta-row">
            <span className="proto-catalog-card-meta-label">File</span>
            <code className="ref-chip ref-chip-path">${item.path}</code>
          </div>
          <div className="proto-catalog-card-meta-row">
            <span className="proto-catalog-card-meta-label">Used by</span>
            <span className="proto-catalog-card-meta-value">
              The prototype skill - the agent reads <code>${item.path}</code> when this slug is the
              committed pick for the ${category} axis.
            </span>
          </div>
          <div className="proto-catalog-card-meta-row">
            <span className="proto-catalog-card-meta-label">Open file</span>
            <a className="proto-catalog-card-meta-link" href=${apiUrl("/" + item.path)} target="_blank" rel="noopener">
              View raw markdown ↗
            </a>
          </div>
        </div>
      `}
    </article>
  `;
}


// ─── SubagentsLanding ─────────────────────────────────────────────────────
// v3.3 - Subagents inventory. Read from /__capabilities (which scans
// .claude/agents/*.md frontmatter). Grouped by family for navigation -
// orchestrators / lenses / visual drawers / simulation / interactive / other -
// since the flat 48-item list is hard to scan.
function SubagentsLanding({ caps }) {
  const agents = (caps && caps.subagents) || [];
  const [openId, setOpenId] = useState(null);
  const [familyFilter, setFamilyFilter] = useState("all");

  const families = {
    orchestrators:   { label: "Orchestrators",            glyph: "⊕", agents: [] },
    lenses:     { label: "Quality lenses",      glyph: "◎", agents: [] },
    visual:     { label: "Visual drawers",      glyph: "◇", agents: [] },
    simulation: { label: "Simulation family",   glyph: "▦", agents: [] },
    interactive:{ label: "Interactive family",  glyph: "✦", agents: [] },
    narrative:  { label: "Narrative family",    glyph: "❋", agents: [] },
    game:       { label: "Game family",         glyph: "▶", agents: [] },
    scrapbook:  { label: "Scrapbook family",    glyph: "✄", agents: [] },
    polish:     { label: "Polish family",       glyph: "✦", agents: [] },
    other:      { label: "Cross-cutting",       glyph: "·", agents: [] },
  };
  const VISUAL_NAMES = new Set(["raster-foreground","raster-photo","vector-icon","vector-mark","shader","particle-2d","particle-gl","lottie","3d","video","motion"]);
  const ORCHESTRATOR_NAMES = new Set([
    "visual-orchestrator",
    "simulation-orchestrator",
    "interactive-media-orchestrator",
    "narrative-experience-orchestrator",
    "game-experience-orchestrator",
    "scrapbook-experience-orchestrator",
    "interactive-polish-orchestrator",
  ]);
  for (const a of agents) {
    const n = a.name || "";
    let key = "other";
    if (ORCHESTRATOR_NAMES.has(n)) key = "orchestrators";
    else if (n.endsWith("-lens") || n.includes("lens")) key = "lenses";
    else if (n.startsWith("sim-"))       key = "simulation";
    else if (n.startsWith("im-"))        key = "interactive";
    else if (n.startsWith("nx-"))        key = "narrative";
    else if (n.startsWith("game-"))      key = "game";
    else if (n.startsWith("scrapbook-") || n.startsWith("sb-")) key = "scrapbook";
    else if (n.startsWith("polish-"))    key = "polish";
    else if (VISUAL_NAMES.has(n))        key = "visual";
    families[key].agents.push(a);
  }

  const visibleFamilies = familyFilter === "all"
    ? Object.entries(families)
    : Object.entries(families).filter(([k]) => k === familyFilter);

  return html`
    <div className="ref-root">
      <${SystemSectionHead}
        name="Subagents"
        count=${agents.length}
        desc=${html`Each subagent is a cold-isolated Claude session with a focused playbook. The orchestrator (or another agent) dispatches one via the Task tool with <code>subagent_type: "${"<name>"}"</code>.`}
      />

      <div className="ref-filter-row">
        <button className=${"ref-filter-chip" + (familyFilter === "all" ? " is-active" : "")} onClick=${() => setFamilyFilter("all")}>All <span className="ref-filter-count">${agents.length}</span></button>
        ${Object.entries(families).filter(([_, f]) => f.agents.length > 0).map(([k, f]) => html`
          <button key=${k} className=${"ref-filter-chip" + (familyFilter === k ? " is-active" : "")} onClick=${() => setFamilyFilter(k)}>
            ${f.label} <span className="ref-filter-count">${f.agents.length}</span>
          </button>
        `)}
      </div>

      ${visibleFamilies.map(([k, f]) => f.agents.length === 0 ? null : html`
        <div key=${k} className="ref-group">
          <div className="ref-group-head">
            <div className="ref-group-title">${f.glyph} ${f.label} <span className="ref-group-count">${f.agents.length}</span></div>
          </div>
          <div className="subagent-list">
            ${f.agents.map(a => html`
              <div key=${a.name} className=${"subagent-card" + (openId === a.name ? " is-open" : "")}>
                <button className="subagent-card-head" onClick=${() => setOpenId(p => p === a.name ? null : a.name)} aria-expanded=${openId === a.name}>
                  <span className="subagent-name"><code>${a.name}</code></span>
                  <span className="subagent-summary">${(a.description || "").slice(0, 120)}${(a.description || "").length > 120 ? "…" : ""}</span>
                  <span className="subagent-toggle">${openId === a.name ? "▼" : "▶"}</span>
                </button>
                ${openId === a.name && html`
                  <div className="subagent-card-body">
                    <div className="subagent-section">
                      <div className="subagent-section-title">Description</div>
                      <div className="subagent-description">${a.description}</div>
                    </div>
                    ${a.tools && html`
                      <div className="subagent-section">
                        <div className="subagent-section-title">Tools available</div>
                        <div className="ref-chip-row">
                          ${a.tools.split(",").map(t => t.trim()).filter(Boolean).map(t => html`
                            <code key=${t} className="ref-chip ref-chip-tool">${t}</code>
                          `)}
                        </div>
                      </div>
                    `}
                    <div className="subagent-section">
                      <div className="subagent-section-title">How to dispatch</div>
                      <div className="subagent-howto">
                        <pre className="subagent-codeblock">Task({
  subagent_type: "${a.name}",
  description:   "Brief one-liner shown in run panel",
  prompt:        "Full envelope - see the playbook for shape"
})</pre>
                      </div>
                    </div>
                    ${a.file && html`
                      <div className="subagent-section">
                        <div className="subagent-section-title">Playbook</div>
                        <code className="ref-chip ref-chip-path">${a.file}</code>
                      </div>
                    `}
                  </div>
                `}
              </div>
            `)}
          </div>
        </div>
      `)}
    </div>
  `;
}


// ─── McpLanding ───────────────────────────────────────────────────────────
// MCP server inventory. Reads /__mcp_catalog (display metadata + a `wired`
// flag computed against .claude/mcp-config.json) and renders a card per
// server. Read-only: editing the catalog or the runtime config still happens
// by editing the JSON files in .claude/. The card surfaces purpose,
// when-to-use, the npx command the daemon spawns, requires-list, and a
// first-call note (e.g. "start Chrome with --remote-debugging-port=9222").
function McpLanding() {
  const [data, setData] = useState(null);
  const [openId, setOpenId] = useState(null);
  // v3.12 - manual add/remove. The form POSTs /__mcp_catalog/add which
  // writes BOTH files (runtime config + display catalog, source:"user");
  // remove unwires + drops user-added catalog entries.
  const [addOpen, setAddOpen] = useState(false);
  const [addForm, setAddForm] = useState({ id: "", label: "", command: "", purpose: "", whenToUse: "", requires: "" });
  const [addBusy, setAddBusy] = useState(false);
  const [addErr, setAddErr] = useState(null);
  const refetch = useCallback(() => {
    fetch(apiUrl("/__mcp_catalog")).then(r => r.ok ? r.json() : null).then(setData).catch(() => {});
  }, []);
  useEffect(() => { refetch(); }, [refetch]);
  useEffect(() => {
    window.addEventListener("th:system-changed", refetch);
    return () => window.removeEventListener("th:system-changed", refetch);
  }, [refetch]);
  const setF = (k) => (e) => setAddForm(p => ({ ...p, [k]: e.target.value }));
  const submitAdd = async () => {
    setAddBusy(true); setAddErr(null);
    try {
      const res = await fetch("/__mcp_catalog/add", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(addForm),
      });
      const j = await res.json().catch(() => null);
      if (!res.ok) throw new Error((j && (j.error || j.hint)) || `HTTP ${res.status}`);
      setAddForm({ id: "", label: "", command: "", purpose: "", whenToUse: "", requires: "" });
      setAddOpen(false);
      refetch();
    } catch (e) {
      setAddErr(e.message || String(e));
    } finally {
      setAddBusy(false);
    }
  };
  const removeServer = async (sid) => {
    if (!(await uiConfirm(`Remove MCP server '${sid}'? It will be unwired from the runtime config.`))) return;
    try {
      const res = await fetch("/__mcp_catalog/remove", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: sid }),
      });
      if (res.ok) refetch();
    } catch {}
  };
  if (!data) {
    return html`<div className="ref-root"><div className="ref-header"><div className="ref-header-title">Loading MCP catalog…</div></div></div>`;
  }
  const servers = data.servers || [];
  const wiredCount = servers.filter(s => s.wired).length;
  return html`
    <div className="ref-root">
      <${SystemSectionHead}
        name="MCP servers"
        count=${servers.length}
        desc=${html`Optional MCP servers the harness exposes to spawned <code>claude</code> subprocesses via <code>--mcp-config</code>. Built-in <code>WebFetch</code> and <code>WebSearch</code> stay primary; these are escalation paths (Chrome for logged-in pages, Figma for design files). Runtime config: <code>${data.configPath}</code>${data.configured ? "" : " (not present - flag will be skipped at spawn-time)"}.`}
        action=${html`<button className="sysadd-bar-btn" type="button" onClick=${() => setAddOpen(true)}>
          <${Icon.Plus}/><span>Add server</span></button>`}
        extra=${html`<div className="sys-shead-extra">${wiredCount} of ${servers.length} wired into the runtime config.</div>`}
      />

      ${addOpen && html`
        <div className="modal-scrim" onMouseDown=${(e) => { if (e.target === e.currentTarget) setAddOpen(false); }}>
          <div className="modal mcp-add-modal" role="dialog" aria-modal="true">
            <div className="modal-head">
              <div>
                <div className="modal-eyebrow">MCP servers</div>
                <div className="modal-title">Add a server</div>
              </div>
              <button className="modal-x" onClick=${() => setAddOpen(false)}>×</button>
            </div>
            <div className="modal-body">
              <div className="mcp-add-form">
                <div className="mcp-add-row">
                  <label className="mcp-add-field">
                    <span>id</span>
                    <input value=${addForm.id} onInput=${setF("id")} placeholder="my-server" spellCheck=${false} autoFocus/>
                  </label>
                  <label className="mcp-add-field">
                    <span>label</span>
                    <input value=${addForm.label} onInput=${setF("label")} placeholder="My Server"/>
                  </label>
                </div>
                <label className="mcp-add-field">
                  <span>command (full command line the daemon spawns)</span>
                  <input value=${addForm.command} onInput=${setF("command")} placeholder="npx -y some-mcp@latest" spellCheck=${false}/>
                </label>
                <label className="mcp-add-field">
                  <span>purpose</span>
                  <input value=${addForm.purpose} onInput=${setF("purpose")} placeholder="What this server does - shown to agents in the capabilities preamble"/>
                </label>
                <label className="mcp-add-field">
                  <span>when to use (optional)</span>
                  <input value=${addForm.whenToUse} onInput=${setF("whenToUse")} placeholder="When should an agent reach for it?"/>
                </label>
                <label className="mcp-add-field">
                  <span>requires (optional, one per line)</span>
                  <textarea rows="2" value=${addForm.requires} onInput=${setF("requires")} placeholder="Node.js / npx on PATH"></textarea>
                </label>
                ${addErr && html`<div className="mcp-add-error">${addErr}</div>`}
              </div>
            </div>
            <div className="modal-foot">
              <span className="mcp-add-hint">Writes both the runtime config and the catalog entry. Tools become <code>mcp__${addForm.id.trim() || "<id>"}__*</code> on the next spawn - agents see it automatically.</span>
              <button className="tbtn tbtn-primary mcp-add-submit" disabled=${addBusy || !addForm.id.trim() || !addForm.command.trim()} onClick=${submitAdd}>
                ${addBusy ? "Adding…" : "Add + wire server"}
              </button>
            </div>
          </div>
        </div>
      `}

      <div className="subagent-list">
        ${servers.map(s => html`
          <div key=${s.id} className=${"subagent-card" + (openId === s.id ? " is-open" : "")}>
            <button className="subagent-card-head" onClick=${() => setOpenId(p => p === s.id ? null : s.id)} aria-expanded=${openId === s.id}>
              <span className="subagent-name">
                <span style=${{ marginRight: "0.5em", opacity: 0.65 }}>${s.icon || "■"}</span>
                <code>${s.label || s.id}</code>
                ${s.wired
                  ? html`<span className="ref-chip" style=${{ marginLeft: "0.6em", background: "rgba(80,180,120,0.16)", color: "#3a9b65" }}>wired</span>`
                  : html`<span className="ref-chip" style=${{ marginLeft: "0.6em", opacity: 0.55 }}>not wired</span>`
                }
              </span>
              <span className="subagent-summary">${(s.purpose || "").slice(0, 140)}${(s.purpose || "").length > 140 ? "…" : ""}</span>
              <span className="subagent-toggle">${openId === s.id ? "▼" : "▶"}</span>
            </button>
            ${openId === s.id && html`
              <div className="subagent-card-body">
                <div className="subagent-section">
                  <div className="subagent-section-title">What it does</div>
                  <div className="subagent-description">${s.purpose}</div>
                </div>
                ${s.whenToUse && html`
                  <div className="subagent-section">
                    <div className="subagent-section-title">When the agent uses it</div>
                    <div className="subagent-description">${s.whenToUse}</div>
                  </div>
                `}
                ${s.command && html`
                  <div className="subagent-section">
                    <div className="subagent-section-title">Spawn command</div>
                    <pre className="subagent-codeblock">${s.command}</pre>
                  </div>
                `}
                ${(s.requires && s.requires.length > 0) && html`
                  <div className="subagent-section">
                    <div className="subagent-section-title">Requires</div>
                    <ul style=${{ margin: 0, paddingLeft: "1.2em", lineHeight: 1.5 }}>
                      ${s.requires.map((r, i) => html`<li key=${i}>${r}</li>`)}
                    </ul>
                  </div>
                `}
                ${s.firstCallNote && html`
                  <div className="subagent-section">
                    <div className="subagent-section-title">First call</div>
                    <div className="subagent-description">${s.firstCallNote}</div>
                  </div>
                `}
                ${s.toolPrefix && html`
                  <div className="subagent-section">
                    <div className="subagent-section-title">Tools exposed as</div>
                    <code className="ref-chip ref-chip-tool">${s.toolPrefix}*</code>
                  </div>
                `}
                ${s.transport && html`
                  <div className="subagent-section">
                    <div className="subagent-section-title">Transport</div>
                    <code className="ref-chip">${s.transport}</code>
                  </div>
                `}
                ${s.source === "user" && html`
                  <div className="subagent-section">
                    <button className="mcp-remove" onClick=${() => removeServer(s.id)}>Remove server</button>
                  </div>
                `}
              </div>
            `}
          </div>
        `)}
      </div>

      <div className="ref-header" style=${{ marginTop: "1.5em" }}>
        <div className="ref-header-meta">
          "+ Add server" above writes both files for you. Hand-editing also
          works: <code>${data.catalogPath}</code> (display metadata) and
          <code>${data.configPath}</code> (the Claude-Code runtime config).
          Both files are mirrored between <code>Woven/</code> and
          <code>Woven IN USE/</code>. Manually wired servers missing a
          catalog entry still surface to agents (and here) as anonymous
          entries.
        </div>
      </div>
    </div>
  `;
}


// ─── NodeKindsLanding ─────────────────────────────────────────────────────
// v3.3 - Node-kinds inventory. Fetches /__kinds/registry for the FULL
// contracts (inputs/outputs/dispatch/fanOut/completion/notes), then groups
// by category and renders an expandable detail block per kind.
function NodeKindsLanding() {
  const [registry, setRegistry] = useState(null);
  const [openKind, setOpenKind] = useState(null);
  useEffect(() => {
    fetch(apiUrl("/__kinds/registry")).then(r => r.ok ? r.json() : null).then(setRegistry).catch(() => {});
  }, []);

  if (!registry) return html`<div className="ref-loading">Loading node kinds…</div>`;

  const KINDS = registry.KINDS || {};
  const entries = Object.entries(KINDS);

  // Group by category
  const groups = {
    container:  { label: "Container",  desc: "Display surfaces - render their content but don't dispatch.", kinds: [] },
    producer:   { label: "Producer",   desc: "Generate output by calling the daemon (skill) or spawning a Claude session (agent).", kinds: [] },
    consumer:   { label: "Consumer",   desc: "Read from an upstream producer's outputsRoot and route every file per consumeFrom rules.", kinds: [] },
    iterator:   { label: "Iterator",   desc: "Run N siblings in parallel (remix / repeater) OR loop two agents (refiner) OR blend N inputs into 1.", kinds: [] },
    decoration: { label: "Decoration", desc: "Pure UI grouping; no behaviour. Manual only.", kinds: [] },
  };
  for (const [kind, c] of entries) {
    const cat = c.category || "other";
    if (groups[cat]) groups[cat].kinds.push([kind, c]);
  }

  return html`
    <div className="ref-root">
      <${SystemSectionHead}
        name="Node kinds"
        count=${entries.length}
        desc="Every node on the workflow canvas has a kind - its contract for inputs / outputs / dispatch / completion. Drop kinds from the Library panel in workflow mode."
      />

      ${Object.entries(groups).map(([catKey, g]) => g.kinds.length === 0 ? null : html`
        <div key=${catKey} className="ref-group">
          <div className="ref-group-head">
            <div className="ref-group-title">${g.label} <span className="ref-group-count">${g.kinds.length}</span></div>
            <div className="ref-group-desc">${g.desc}</div>
          </div>
          <div className="kind-list">
            ${g.kinds.map(([kindName, c]) => html`
              <div key=${kindName} className=${"kind-card" + (openKind === kindName ? " is-open" : "")}>
                <button className="kind-card-head" onClick=${() => setOpenKind(p => p === kindName ? null : kindName)} aria-expanded=${openKind === kindName}>
                  <code className="kind-name">${kindName}</code>
                  <span className="kind-title">${c.title || kindName}</span>
                  <span className=${"kind-dispatch kind-dispatch-" + (c.dispatch || "none").replace(/[^a-z]/gi, "-")}>${c.dispatch || "none"}</span>
                  <span className="kind-toggle">${openKind === kindName ? "▼" : "▶"}</span>
                </button>
                ${openKind === kindName && html`
                  <div className="kind-card-body">
                    ${c.notes && html`
                      <div className="kind-section">
                        <div className="kind-section-title">What it does</div>
                        <div className="kind-notes">${c.notes}</div>
                      </div>
                    `}
                    ${c.inputs && Object.keys(c.inputs).length > 0 && html`
                      <div className="kind-section">
                        <div className="kind-section-title">Inputs</div>
                        <div className="kind-fields">
                          ${Object.entries(c.inputs).map(([k, spec]) => html`
                            <div key=${k} className="kind-field">
                              <code className="kind-field-name">${k}</code>
                              <code className=${"kind-field-type kind-field-type-" + (spec.type || "any")}>${spec.type || "any"}</code>
                              ${spec.required && html`<span className="kind-field-required">required</span>`}
                              ${spec.userEditable === false && html`<span className="kind-field-locked">system-set</span>`}
                              ${spec.label && html`<span className="kind-field-label">${spec.label}</span>`}
                              ${spec.doc && html`<div className="kind-field-doc">${spec.doc}</div>`}
                            </div>
                          `)}
                        </div>
                      </div>
                    `}
                    ${c.outputs && Object.keys(c.outputs).length > 0 && html`
                      <div className="kind-section">
                        <div className="kind-section-title">Outputs</div>
                        <div className="kind-fields">
                          ${Object.entries(c.outputs).map(([k, spec]) => html`
                            <div key=${k} className="kind-field">
                              <code className="kind-field-name">${k}</code>
                              <code className=${"kind-field-type kind-field-type-" + (spec.type || "any")}>${spec.type || "any"}</code>
                              ${spec.required && html`<span className="kind-field-required">required</span>`}
                              ${spec.doc && html`<div className="kind-field-doc">${spec.doc}</div>`}
                            </div>
                          `)}
                        </div>
                      </div>
                    `}
                    ${c.outputsRoot && html`
                      <div className="kind-section kind-section-row">
                        <div className="kind-section-title">outputsRoot</div>
                        <code className="ref-chip ref-chip-path">${c.outputsRoot}</code>
                      </div>
                    `}
                    ${c.fanOut && html`
                      <div className="kind-section">
                        <div className="kind-section-title">Fan-out</div>
                        <div className="kind-fanout">
                          <div><strong>kind:</strong> ${c.fanOut.kind} · <strong>isolation:</strong> ${c.fanOut.isolation} · <strong>parallelism:</strong> ${c.fanOut.parallelism}</div>
                          <div><strong>count:</strong> <code>${c.fanOut.count}</code> · <strong>diverger:</strong> <code>${c.fanOut.diverger}</code></div>
                        </div>
                      </div>
                    `}
                    ${c.completion && Array.isArray(c.completion.requires) && c.completion.requires.length > 0 && html`
                      <div className="kind-section">
                        <div className="kind-section-title">Completion (required for status:done)</div>
                        <ul className="kind-completion-list">
                          ${c.completion.requires.map((req, i) => html`<li key=${i}><code>${req}</code></li>`)}
                        </ul>
                      </div>
                    `}
                    <div className="kind-section kind-howto">
                      <div className="kind-section-title">How to use</div>
                      <div className="kind-howto-body">
                        ${c.dispatch === "none" && html`<span>User-driven. Drop on canvas, edit inline. No Run button or it's user-triggered (e.g. ▶ Run on a prototype reloads the iframe).</span>`}
                        ${c.dispatch === "inline-server-call" && html`<span>Click ▶ Run on the node and the daemon makes a synchronous call. Result lands in the node's output. Use for cheap text ops.</span>`}
                        ${c.dispatch === "single-subprocess" && html`<span>Click ▶ Run on the node - a Claude Code subprocess spawns with the per-id preamble. Visible in the run panel; click ⏹ to stop.</span>`}
                        ${c.dispatch === "task-subagents" && html`<span>Click ▶ Run on the node - N cold-isolated Task subagents fan out in parallel. Each writes to its own variant folder; downstream consumer routes files per consumeFrom rules.</span>`}
                        ${c.dispatch === "client-iterator" && html`<span>Browser-side loop. Hits the daemon for child agent dispatches; runs until a [STOP] sentinel or maxTurns.</span>`}
                      </div>
                    </div>
                  </div>
                `}
              </div>
            `)}
          </div>
        </div>
      `)}
    </div>
  `;
}


// ─── OrchestratorsLanding ──────────────────────────────────────────────────────
// v3.3 - Orchestrator registry surface. Fetches `/__orchestrators` (which aggregates
// `.claude/agents/*.manifest.json` + the project's disable state), renders one
// card per orchestrator with description / triggers / dispatches / skills /
// node-kinds, and a toggle that POSTs `/__orchestrators/disable` to persist.
//
// Adding a new orchestrator is a single-file operation: drop a manifest next to
// the playbook and this view picks it up - no UI code change needed.
function OrchestratorsLanding({ scopeLabel, onSpawnSystemThread }) {
  const [data, setData] = useState(null);
  const [err, setErr]   = useState(null);
  const [busy, setBusy] = useState(null);

  const load = async () => {
    setErr(null);
    try {
      const r = await fetch(apiUrl("/__orchestrators"));
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
      setData(j);
    } catch (e) {
      setErr(e.message || String(e));
    }
  };
  useEffect(() => { load(); }, []);

  const toggle = async (orchestratorId, enabled) => {
    setBusy(orchestratorId);
    try {
      const r = await fetch(apiUrl("/__orchestrators/disable"), {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({ orchestratorId, enabled }),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
      await load();
    } catch (e) {
      setErr(e.message || String(e));
    } finally {
      setBusy(null);
    }
  };

  if (err)  return html`<div className="orchestrators-error">Failed to load orchestrators: ${err}</div>`;
  if (!data) return html`<div className="orchestrators-loading">Loading orchestrators…</div>`;

  return html`
    <div className="orchestrators-root">
      <${SystemSectionHead}
        name="Orchestrators"
        count=${data.count}
        desc=${html`Orchestrators dispatch families of subagents to produce complex artefacts (images, simulations, interactive pieces). Each is auto-discovered from its <code>.claude/agents/${"<name>"}.manifest.json</code>. Disabling one removes its hard-rule prompt from every spawned Claude session in this ${scopeLabel || "workspace"} - the agent stops auto-dispatching it, but you can still invoke it manually by subagent name.`}
        action=${onSpawnSystemThread && html`<${SystemAddBar} kind="orchestrators" onSpawn=${onSpawnSystemThread}/>`}
        extra=${html`<div className="sys-shead-extra">scope: ${scopeLabel || "workspace"}${data.disabledIds && data.disabledIds.length > 0 ? ` · ${data.disabledIds.length} disabled` : ""}</div>`}
      />
      <div className="orchestrators-grid">
        ${data.orchestrators.map(p => html`
          <${OrchestratorCard}
            key=${p.id}
            orchestrator=${p}
            busy=${busy === p.id}
            onToggle=${() => toggle(p.id, !p.enabled)}
          />
        `)}
      </div>
      ${data.orchestrators.length === 0 && html`
        <div className="orchestrators-empty">
          No orchestrator manifests found under <code>.claude/agents/*.manifest.json</code>.
          Drop a manifest there next to a orchestrator's playbook to register it.
        </div>
      `}
    </div>
  `;
}

// v3.13 - Per-orchestrator LLM model override. One dropdown per card: the
// model THIS orchestrator's dispatched drawers run on, independent of the
// global agent-capability default. "Agent default" (empty value) clears the
// override so the orchestrator follows whatever the chat agent uses. Stored
// in localStorage["th.editor.orchestrator-models.v1"] and synced to the
// daemon so the capabilities preamble can steer the dispatch per orchestrator.
function OrchestratorModelSelect({ orchestratorId, disabled }) {
  const [override, setOverride] = useState(() => getOrchestratorModel(orchestratorId));
  useEffect(() => {
    const on = () => setOverride(getOrchestratorModel(orchestratorId));
    window.addEventListener("th:orchestrator-models-changed", on);
    return () => window.removeEventListener("th:orchestrator-models-changed", on);
  }, [orchestratorId]);
  const choices = useMemo(() => listOrchestratorModelChoices(), []);
  const current = (override && override.model) || "";
  return html`
    <label
      className="orchestrator-card-model"
      data-active=${current ? "true" : "false"}
      title=${disabled
        ? "Enable this orchestrator to set its model"
        : "Model this orchestrator's dispatched subagents run on. ‘Agent default’ follows the global chat/agent model."}
      onClick=${(e) => e.stopPropagation()}
    >
      <span className="orchestrator-card-model-icon" aria-hidden="true">◇</span>
      <select
        className="orchestrator-card-model-select"
        value=${current}
        disabled=${disabled}
        onChange=${(e) => {
          const id = e.target.value;
          saveOrchestratorModel(orchestratorId, id ? { provider: "anthropic", model: id } : null);
        }}
      >
        <option value="">Agent default</option>
        ${choices.map(m => html`<option key=${m.id} value=${m.id}>${m.label || m.id}</option>`)}
      </select>
    </label>
  `;
}

function OrchestratorCard({ orchestrator, busy, onToggle }) {
  const p = orchestrator;
  const [expanded, setExpanded] = useState(false);
  const d = p.dispatches || {};
  // Flatten dispatched subagent groups for a single count + glance grouping.
  const dispatchGroups = [];
  for (const [key, label] of [["research", "Research drawers"],
                                ["components", "Component drawers"],
                                ["drawers", "Per-medium drawers"],
                                ["lenses", "Quality lenses"],
                                ["collaborators", "Collaborates with"]]) {
    const arr = d[key];
    if (Array.isArray(arr) && arr.length > 0) dispatchGroups.push({ key, label, items: arr });
  }
  const totalDispatched = dispatchGroups.reduce((acc, g) => acc + g.items.length, 0);

  const nodeKinds      = p.nodeKinds || {};
  const containerKinds = nodeKinds.container || [];
  const agentOverrides = nodeKinds.agent_overrides || [];
  const trios          = nodeKinds.trios_scaffolded || [];

  return html`
    <div
      className=${"orchestrator-card" + (p.enabled ? "" : " is-disabled") + (expanded ? " is-expanded" : " is-collapsed")}
      data-orchestrator-id=${p.id}
      data-enabled=${p.enabled ? "true" : "false"}
    >
      <div
        className="orchestrator-card-head"
        onClick=${(e) => { if (!e.target.closest(".orchestrator-toggle") && !e.target.closest(".orchestrator-card-model")) setExpanded(x => !x); }}
        title=${expanded ? "Click to collapse" : "Click to expand"}
        style=${{ cursor: "pointer" }}
      >
        <span className="orchestrator-card-disclosure" aria-hidden="true">${expanded ? "▼" : "▶"}</span>
        ${p.art
          ? html`<img className="orchestrator-card-art" src=${p.art} alt="" loading="lazy"/>`
          : html`<div className="orchestrator-card-art orchestrator-card-art-ph" aria-hidden="true" title="No art yet - placeholder"><${Icon.Flow}/></div>`}
        <div className="orchestrator-card-head-text">
          <div className="orchestrator-card-name">
            <span className="orchestrator-card-label">${p.label}</span>
            <code className="orchestrator-card-id">${p.id}</code>
            <span className="orchestrator-card-version">${p.version || ""}</span>
          </div>
          <div className="orchestrator-card-tagline">${p.tagline}</div>
        </div>
        <${OrchestratorModelSelect} orchestratorId=${p.id} disabled=${!p.enabled}/>
        <button
          className=${"orchestrator-toggle" + (busy ? " is-busy" : "")}
          data-enabled=${p.enabled ? "true" : "false"}
          disabled=${busy}
          onClick=${(e) => { e.stopPropagation(); onToggle(); }}
          title=${p.enabled
            ? "Disable this orchestrator - its dispatch hard-rule will be removed from the spawn preamble"
            : "Enable this orchestrator - restore its dispatch hard-rule in the spawn preamble"}
        >
          <span className="orchestrator-toggle-track"><span className="orchestrator-toggle-knob"/></span>
          <span className="orchestrator-toggle-label">${p.enabled ? "ON" : "OFF"}</span>
        </button>
      </div>

      ${expanded && html`
      <div className="orchestrator-card-description">${p.description}</div>

      ${Array.isArray(p.triggers) && p.triggers.length > 0 && html`
        <div className="orchestrator-section">
          <div className="orchestrator-section-title">Triggers (${p.triggers.length})</div>
          <ul className="orchestrator-trigger-list">
            ${p.triggers.map((t, i) => html`
              <li key=${i} className="orchestrator-trigger">
                <span className=${"orchestrator-trigger-mode orchestrator-trigger-mode-" + (t.mode || "other")}>${t.mode || "other"}</span>
                <span className="orchestrator-trigger-title">${t.title}</span>
                <div className="orchestrator-trigger-rule">${t.rule}</div>
                ${t.ruleSource && html`<div className="orchestrator-trigger-source">↳ ${t.ruleSource}</div>`}
              </li>
            `)}
          </ul>
        </div>
      `}

      ${dispatchGroups.length > 0 && html`
        <div className="orchestrator-section">
          <div className="orchestrator-section-title">Subagents (${totalDispatched})</div>
          ${dispatchGroups.map(g => html`
            <div key=${g.key} className="orchestrator-dispatch-group">
              <div className="orchestrator-dispatch-group-title">${g.label} <span className="orchestrator-dispatch-count">${g.items.length}</span></div>
              <div className="orchestrator-chip-row">
                ${g.items.map(name => html`<code key=${name} className="orchestrator-chip orchestrator-chip-agent">${name}</code>`)}
              </div>
            </div>
          `)}
        </div>
      `}

      ${Array.isArray(p.skills) && p.skills.length > 0 && html`
        <div className="orchestrator-section">
          <div className="orchestrator-section-title">Skills (${p.skills.length})</div>
          <div className="orchestrator-chip-row">
            ${p.skills.map(s => html`<code key=${s} className="orchestrator-chip orchestrator-chip-skill">${s}</code>`)}
          </div>
        </div>
      `}

      ${(containerKinds.length > 0 || agentOverrides.length > 0 || trios.length > 0) && html`
        <div className="orchestrator-section">
          <div className="orchestrator-section-title">Node kinds summoned</div>
          ${containerKinds.length > 0 && html`
            <div className="orchestrator-dispatch-group">
              <div className="orchestrator-dispatch-group-title">Container kinds <span className="orchestrator-dispatch-count">${containerKinds.length}</span></div>
              <div className="orchestrator-chip-row">
                ${containerKinds.map(k => html`<code key=${k} className="orchestrator-chip orchestrator-chip-kind">${k}</code>`)}
              </div>
            </div>
          `}
          ${agentOverrides.length > 0 && html`
            <div className="orchestrator-dispatch-group">
              <div className="orchestrator-dispatch-group-title">Agent per-id overrides <span className="orchestrator-dispatch-count">${agentOverrides.length}</span></div>
              <div className="orchestrator-chip-row">
                ${agentOverrides.map(k => html`<code key=${k} className="orchestrator-chip orchestrator-chip-override">${k}</code>`)}
              </div>
            </div>
          `}
          ${trios.length > 0 && html`
            <div className="orchestrator-dispatch-group">
              <div className="orchestrator-dispatch-group-title">Trios scaffolded <span className="orchestrator-dispatch-count">${trios.length}</span></div>
              <div className="orchestrator-chip-row">
                ${trios.map(k => html`<code key=${k} className="orchestrator-chip orchestrator-chip-trio">${k}</code>`)}
              </div>
            </div>
          `}
        </div>
      `}

      ${p.documents && (p.documents.designDoc || p.documents.calibration || p.documents.policy) && html`
        <div className="orchestrator-section orchestrator-section-docs">
          <div className="orchestrator-section-title">Reference</div>
          <div className="orchestrator-doc-list">
            ${p.documents.designDoc   && html`<code className="orchestrator-doc">${p.documents.designDoc}</code>`}
            ${p.documents.calibration && html`<code className="orchestrator-doc">${p.documents.calibration}</code>`}
            ${p.documents.policy      && html`<code className="orchestrator-doc">${p.documents.policy}</code>`}
            ${p.playbookPath           && html`<code className="orchestrator-doc">${p.playbookPath}</code>`}
          </div>
        </div>
      `}
      `}
    </div>
  `;
}

// v3.5.x - Per-project diamond field for landing cards that don't have a
// thumbnail prototype set yet. CSS+SVG diamond tile + JS-driven cursor
// lighting via CSS custom properties (--mx, --my, --hover). WebGL is OUT:
// a 21-project landing burns past the browser's per-page WebGL context cap
// and contexts start getting lost. The CSS approach scales unboundedly,
// honours prefers-reduced-motion automatically (no rAF), and stays in
// brand by sharing the same diamond geometry as landing-shaders.
//
// Each card hashes its project ID to pick a tint from LANDING_CARD_PALETTE
// (the SVG inherits that tint via a `background-color` blend), then a
// radial-gradient layered on top follows the cursor for the live lighting
// effect. The blob is animated by writing the cursor x/y into the CSS
// vars from a pointermove handler on the host card.
function LandingCardField({ seed, hostRef }) {
  const rootRef = useRef(null);
  useEffect(() => {
    const root = rootRef.current;
    // Walk up to the closest interactive ancestor that actually receives
    // pointer events. The `.landing-card-thumb` strip is `pointer-events:
    // none` (clicks fall through to the card) so we must hook the listeners
    // on `.landing-card` itself - that's the element the user's cursor is
    // really over.
    const host = (hostRef && hostRef.current)
              || (root && root.closest && root.closest(".landing-card"))
              || (root && root.parentElement);
    if (!root || !host) return;
    const pal = (typeof window !== "undefined" && window.LANDING_CARD_PALETTE) || [[0.96, 0.96, 0.94]];
    // Pick THREE seeded colours from the palette so the gradient blends a
    // little mix - never just one flat tint. The three offsets are pulled
    // from the same FNV-1a hash so the choice is stable across reloads
    // (same project → same trio), but visually distinct from its neighbour.
    let h = 0x811c9dc5 >>> 0;
    for (let i = 0; i < (seed || "").length; i++) {
      h ^= (seed || "").charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    const idx1 = h % pal.length;
    const idx2 = (Math.floor(h / pal.length) + 3) % pal.length;
    const idx3 = (Math.floor(h / (pal.length * pal.length)) + 7) % pal.length;
    const angle = (h % 360);
    const toCss = (t) => `rgb(${(t[0]*255).toFixed(0)} ${(t[1]*255).toFixed(0)} ${(t[2]*255).toFixed(0)})`;
    root.style.setProperty("--field-c1", toCss(pal[idx1]));
    root.style.setProperty("--field-c2", toCss(pal[idx2]));
    root.style.setProperty("--field-c3", toCss(pal[idx3]));
    root.style.setProperty("--field-angle", angle + "deg");
    // Cursor tracking - write the cursor position (relative to the card)
    // into CSS vars the gradient consumes. Hover signal eases up/down so
    // the lighting blooms in instead of snapping.
    let hover = 0, target = 0;
    let raf = 0;
    function tick() {
      hover += (target - hover) * 0.15;
      root.style.setProperty("--field-hover", hover.toFixed(3));
      if (Math.abs(target - hover) > 0.005) raf = requestAnimationFrame(tick);
      else raf = 0;
    }
    function onMove(e) {
      const r = root.getBoundingClientRect();
      const x = ((e.clientX - r.left) / r.width) * 100;
      const y = ((e.clientY - r.top) / r.height) * 100;
      root.style.setProperty("--field-mx", x.toFixed(1) + "%");
      root.style.setProperty("--field-my", y.toFixed(1) + "%");
    }
    function onEnter() { target = 1; if (!raf) raf = requestAnimationFrame(tick); }
    function onLeave() { target = 0; if (!raf) raf = requestAnimationFrame(tick); }
    host.addEventListener("pointermove", onMove);
    host.addEventListener("pointerenter", onEnter);
    host.addEventListener("pointerleave", onLeave);
    return () => {
      if (raf) cancelAnimationFrame(raf);
      try {
        host.removeEventListener("pointermove", onMove);
        host.removeEventListener("pointerenter", onEnter);
        host.removeEventListener("pointerleave", onLeave);
      } catch {}
    };
  }, [seed, hostRef]);
  return html`<div ref=${rootRef} className="landing-card-field" aria-hidden="true"/>`;
}

// v3.5.x - Thumbnail-iframe scale-to-fit. The iframe renders at a fixed
// 1280×720 viewport so the page lays out as it would on desktop; this
// effect measures the strip and writes a --thumb-scale CSS var so the
// transform: scale(var(--thumb-scale)) fits the page into the strip's
// actual on-screen width. ResizeObserver re-fires on every grid reflow.
function LandingCardThumbIframe({ src, title }) {
  const wrapRef = useRef(null);
  const iframeRef = useRef(null);
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const update = () => {
      const w = wrap.getBoundingClientRect().width;
      if (w > 0) wrap.style.setProperty("--thumb-scale", String(w / 1280));
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(wrap);
    return () => ro.disconnect();
  }, []);
  return html`
    <div ref=${wrapRef} className="landing-card-thumb-iframe-wrap">
      <iframe
        ref=${iframeRef}
        className="landing-card-thumb-iframe"
        src=${src}
        title=${title}
        sandbox="allow-scripts allow-same-origin"
        scrolling="no"
        loading="lazy"
        tabIndex=${-1}
      />
    </div>
  `;
}

// v3.6 - Static thumbnail capture. The daemon screenshots the chosen page to
// <project>/.thumbnail.png when the thumbnail is set (headless Chrome at the
// same 1280×720 viewport), so the landing renders one cheap <img> per card
// instead of booting a whole page runtime in a live iframe. The iframe stays
// as the fallback: capture missing / not landed yet / 404 → onError swaps it
// back in. `version` is the capture mtime (screenshotV) for cache busting.
function LandingCardThumbShot({ projectId, version, src, title }) {
  const [failed, setFailed] = useState(false);
  if (failed) return html`<${LandingCardThumbIframe} src=${src} title=${title}/>`;
  return html`
    <img
      className="landing-card-thumb-img"
      src=${"/.thumbnail.png?project=" + encodeURIComponent(projectId) + "&v=" + (version || 0)}
      alt=${title}
      loading="lazy"
      draggable=${false}
      onError=${() => setFailed(true)}
    />
  `;
}

/* ────────── Share mode - landing "Shares" tab ──────────
   Lists every shared prototype across the workspace with live tunnel
   status (GET /__shares, polled while the tab is open), the public
   *.trycloudflare.com URL (copy / open, with a "URL changed" warning when
   a daemon restart minted a fresh quick-tunnel hostname), per-share
   comment counts, and start / stop / delete / email-gate controls.
   Server side: editor/shares.py. See docs/features/share-mode.md. */
function SharesLanding({ onCountChange }) {
  const [data, setData] = useState(null);       // {shares, cloudflared, gatePort}
  const [busy, setBusy] = useState({});         // shareId → true while an op runs
  const [err, setErr] = useState(null);
  const [copiedId, setCopiedId] = useState(null);
  const [query, setQuery] = useState("");       // free-text filter
  const [projectFilter, setProjectFilter] = useState("");  // "" = all projects
  const [hkOpen, setHkOpen] = useState(false);  // Housekeeping (screenshot cleanup) overlay
  const reload = useCallback(() => {
    fetch("/__shares")
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error("daemon unreachable"))))
      .then((j) => {
        setData(j);
        if (onCountChange) onCountChange((j.shares || []).filter(s => !s.liveOnly).length);
      })
      .catch(() => {});
  }, [onCountChange]);
  useEffect(() => {
    reload();
    const t = setInterval(reload, 5000);
    return () => clearInterval(t);
  }, [reload]);

  const flashErr = (msg) => { setErr(msg); setTimeout(() => setErr(null), 6000); };
  const op = async (id, action, body) => {
    setBusy((b) => ({ ...b, [id]: true }));
    try {
      const r = await fetch(`/__share/${id}/${action}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body || {}),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || `${action} failed`);
      reload();
    } catch (e) {
      flashErr(String(e.message || e));
    } finally {
      setBusy((b) => { const n = { ...b }; delete n[id]; return n; });
    }
  };
  const copyUrl = async (s) => {
    if (!s.shareUrl) return;
    try { await navigator.clipboard.writeText(s.shareUrl); } catch {}
    setCopiedId(s.id);
    setTimeout(() => setCopiedId((p) => (p === s.id ? null : p)), 1600);
    // Copying the fresh URL acknowledges the "URL changed" warning.
    if (s.urlChanged) op(s.id, "ack_url");
  };
  // Live-session / Go-Live management moved OUT of this landing tab into the
  // top-bar Share menu (ShareMenuButton → Project tab) - its old home here was
  // the wrong location. This tab now only manages the tunnels + links +
  // comments for shared prototypes.

  // Exclude the project's multiplayer transport share - it's not a published
  // prototype, it just hosts the live session (managed from the Share menu).
  const shares = ((data && data.shares) || []).filter(s => !s.liveOnly);
  const cfMissing = data && data.cloudflared && !data.cloudflared.found;
  const wovenAvail = !!(data && data.woven && data.woven.available);
  // Distinct projects (for the filter dropdown) + the active text/project filter.
  const projectIds = [...new Set(shares.map((s) => s.project))].sort();
  const q = query.trim().toLowerCase();
  const filteredShares = shares.filter((s) => {
    if (projectFilter && s.project !== projectFilter) return false;
    if (!q) return true;
    return [s.label, s.project, s.prototype].some((v) => (v || "").toLowerCase().includes(q));
  });
  const STATUS_META = {
    "running":        { dot: "ok",    label: "Running" },
    "starting":       { dot: "warn",  label: "Starting…" },
    "stopped":        { dot: "idle",  label: "Stopped" },
    "exited":         { dot: "err",   label: "Tunnel dropped" },
    "error":          { dot: "err",   label: "Error" },
    "no-cloudflared": { dot: "err",   label: "cloudflared missing" },
  };

  return html`
    <div className="shares-landing">
      ${err && html`<div className="shares-error-banner">${err}</div>`}
      <div className="shares-served-banner">
        <span className="shares-served-dot"></span>
        <span>Links are served from <b>this computer</b> - people can only open them while it's on and the share is running.</span>
      </div>
      ${shares.length > 0 && html`
        <div className="shares-toolbar">
          <input
            className="shares-search"
            type="search"
            placeholder="Search shares…"
            value=${query}
            onInput=${(e) => setQuery(e.target.value)}
          />
          ${projectIds.length > 1 && html`
            <select className="shares-project-filter" value=${projectFilter}
              onChange=${(e) => setProjectFilter(e.target.value)}>
              <option value="">All projects</option>
              ${projectIds.map((p) => html`<option key=${p} value=${p}>${p}</option>`)}
            </select>
          `}
          <span className="shares-toolbar-count">${filteredShares.length} of ${shares.length}</span>
          <button className="shares-btn shares-hk-open" onClick=${() => setHkOpen(true)}
            title="Housekeeping - review and bulk-delete comment screenshots across shared prototypes">
            <${Icon.Image}/> Housekeeping
          </button>
        </div>
      `}
      ${cfMissing && html`
        <div className="shares-cf-hint">
          <b>cloudflared is not installed.</b> Shares publish through Cloudflare quick
          tunnels - install it once via <b>Settings ⚙ → Local skills → Install cloudflared</b>
          (or <code>brew install cloudflared</code>), then Start any share.
        </div>
      `}
      ${data && shares.length === 0 && html`
        <div className="shares-empty">
          <div className="shares-empty-glyph"><${Icon.Globe}/></div>
          <b>No shared prototypes yet</b>
          <p>
            Open a project's workflow canvas, select a prototype node, and hit the
            <b> Share</b> action. Woven publishes the live prototype through a Cloudflare
            quick tunnel - anyone with the link can browse it and pin comments on
            specific elements; those comments land back on the prototype node, ready
            to send to the build agent.
          </p>
        </div>
      `}
      ${shares.length > 0 && filteredShares.length === 0 && html`
        <div className="shares-empty" style=${{ padding: "28px 16px" }}>
          <b>No shares match</b>
          <p>Try a different search${projectFilter ? " or clear the project filter" : ""}.</p>
        </div>
      `}
      ${filteredShares.map((s) => {
        const st = STATUS_META[s.status] || STATUS_META.stopped;
        const isBusy = !!busy[s.id];
        const cc = s.commentCounts || {};
        // Per-share preview. URL carries the share's OWN project (the landing
        // has no active project, so apiUrl() can't add it) + ?v=mtime so a
        // re-capture busts the cache.
        const thumbSrc = s.hasThumbnail
          ? `/__share_thumbnail?project=${encodeURIComponent(s.project)}&prototype=${encodeURIComponent(s.prototype)}&v=${s.thumbnailV || 0}`
          : null;
        return html`
          <div className="shares-row" key=${s.id}>
            <div className="shares-row-thumb" title=${thumbSrc ? "Preview captured at share time - refreshes when the prototype updates" : "Preview will appear once captured"}>
              ${thumbSrc
                ? html`<img src=${thumbSrc} alt=${"Preview of " + s.label} loading="lazy"/>`
                : html`<div className="shares-row-thumb-empty"><${Icon.Image}/></div>`}
            </div>
            <div className="shares-row-body">
            <div className="shares-row-main">
              <span className=${"shares-dot is-" + st.dot} title=${s.error || st.label}></span>
              <div className="shares-row-id">
                <div className="shares-row-label">${s.label}</div>
                <div className="shares-row-sub">
                  <code>${s.project}</code> · <code>source/${s.prototype}/</code>
                  <span className="shares-row-status">${st.label}</span>
                  ${s.emailGate && html`<span className="shares-chip" title="Visitors must leave a name + email to comment">email gate</span>`}
                </div>
              </div>
              <div className="shares-row-comments" title=${`${cc.open || 0} open · ${cc.done || 0} done · ${cc.archived || 0} archived`}>
                <${Icon.Comment}/> ${cc.open || 0}<span className="shares-row-comments-total">/${cc.total || 0}</span>
              </div>
              <div className="shares-row-actions">
                <${ShareModeToggle} quickOn=${s.quickOn} wovenOn=${s.wovenOn} wovenAvail=${wovenAvail} busy=${isBusy}
                  onToggle=${(which, on) => op(s.id, "update", which === "woven" ? { wovenOn: on } : { quickOn: on })}/>
                ${s.status === "running" || s.status === "starting"
                  ? html`<button className="shares-btn" disabled=${isBusy}
                      onClick=${() => op(s.id, "stop")} title="Stop the tunnel - the public URL goes dark">Stop</button>`
                  : html`<button className="shares-btn shares-btn-primary" disabled=${isBusy || cfMissing}
                      title=${cfMissing ? "Install cloudflared first" : (s.mode === "woven" ? "Start the stable tunnel (same URL every time)" : "Start a randomised tunnel (the URL will be new)")}
                      onClick=${() => op(s.id, "start")}>Start</button>`}
                <button className="shares-btn" disabled=${isBusy}
                  title=${s.emailGate ? "Switch to open commenting (name only)" : "Require name + email to comment"}
                  onClick=${() => op(s.id, "update", { emailGate: !s.emailGate })}
                >${s.emailGate ? "Gate: email" : "Gate: open"}</button>
                <button className="shares-btn shares-btn-danger" disabled=${isBusy}
                  title="Delete the share - kills the tunnel and revokes the link (comments are kept in the project)"
                  onClick=${async () => { if (await uiConfirm(`Delete share "${s.label}"? The link stops working immediately.`)) op(s.id, "delete"); }}
                >Delete</button>
              </div>
            </div>
            <div className="shares-row-url">
              ${s.shareUrl
                ? html`
                    <code key="url" className="shares-url" title=${s.shareUrl}>${s.shareUrl}</code>
                    <button key="copy" className="shares-btn" onClick=${() => copyUrl(s)}>${copiedId === s.id ? "Copied ✓" : "Copy"}</button>
                    <button key="open" className="shares-btn" onClick=${() => window.open(s.shareUrl, "_blank")}>Open</button>
                  `
                : html`<span className="shares-url-none">
                    ${s.status === "starting" ? "Waiting for tunnel URL…"
                      : s.status === "no-cloudflared" ? "Install cloudflared to publish"
                      : "Not published - start the tunnel to get a link"}
                  </span>`}
              ${s.urlChanged && html`
                <span className="shares-url-changed" title=${"Previous URL: " + (s.prevUrl || "-") + " - quick-tunnel URLs change on every restart. Copy + resend the new link."}>
                  ⚠ URL changed
                </span>
              `}
            </div>
            ${s.error && s.status === "error" && html`<div className="shares-row-error">${s.error}</div>`}
            </div>
          </div>
        `;
      })}
      ${hkOpen && html`<${ShareHousekeepingModal} onClose=${() => { setHkOpen(false); reload(); }}/>`}
    </div>
  `;
}

/* ShareHousekeepingModal - reached from the Shares tab's "Housekeeping" button.
   Two views in one overlay:
     1. Group list - every prototype that has been shared (or still has review
        comments) across all projects, with how many comments carry a page
        screenshot and the disk those screenshots occupy (GET /__share_housekeeping).
     2. Per-prototype table - all comments for the picked group, filterable by
        status / image presence / text, with per-row + select-all checkboxes and
        a bulk "Delete images" action (POST /__share_comments op:"clear_shots").
   Deleting only strips the screenshot (file + shot/shotAt fields); the comment
   thread itself is left intact. Cross-project, so URLs carry the group's own
   project id rather than going through apiUrl (which forces the active one). */
function ShareHousekeepingModal({ onClose }) {
  const [groups, setGroups] = useState(null);   // null = loading
  const [err, setErr] = useState(null);
  const [sel, setSel] = useState(null);         // picked group {project, prototype, label}
  const [comments, setComments] = useState(null);
  const [detailErr, setDetailErr] = useState(null);
  const [filter, setFilter] = useState("withImages");
  const [q, setQ] = useState("");
  const [picked, setPicked] = useState({});     // commentId → true
  const [busy, setBusy] = useState(false);

  const loadGroups = useCallback(() => {
    fetch("/__share_housekeeping")
      .then(r => (r.ok ? r.json() : Promise.reject(new Error("failed to load"))))
      .then(j => setGroups(j.groups || []))
      .catch(e => setErr(String(e.message || e)));
  }, []);
  useEffect(() => { loadGroups(); }, [loadGroups]);

  const loadComments = useCallback((g) => {
    setComments(null); setDetailErr(null);
    fetch(`/__share_comments?project=${encodeURIComponent(g.project)}&prototype=${encodeURIComponent(g.prototype)}`)
      .then(r => (r.ok ? r.json() : Promise.reject(new Error("failed to load comments"))))
      .then(j => setComments(j.comments || []))
      .catch(e => setDetailErr(String(e.message || e)));
  }, []);

  const openGroup = (g) => { setSel(g); setPicked({}); setFilter("withImages"); setQ(""); loadComments(g); };
  const shotUrl = (g, c) => `/__share_comment_shot?project=${encodeURIComponent(g.project)}&comment=${encodeURIComponent(c.id)}&v=${encodeURIComponent(c.shotAt || "")}`;

  const visible = useMemo(() => {
    let list = comments || [];
    if (filter === "withImages") list = list.filter(c => c.shot);
    else if (filter !== "all") list = list.filter(c => (c.status || "open") === filter);
    const needle = q.trim().toLowerCase();
    if (needle) list = list.filter(c =>
      ((c.text || "") + " " + ((c.author && c.author.name) || "") + " " + (c.page || "")).toLowerCase().includes(needle));
    return list;
  }, [comments, filter, q]);
  const withImageVisible = useMemo(() => visible.filter(c => c.shot), [visible]);
  const pickedIds = Object.keys(picked).filter(id => picked[id]);
  const allChecked = withImageVisible.length > 0 && withImageVisible.every(c => picked[c.id]);
  const toggleAll = () => {
    if (allChecked) { setPicked({}); return; }
    const n = {}; withImageVisible.forEach(c => { n[c.id] = true; }); setPicked(n);
  };

  const fmtBytes = (n) => {
    n = n || 0;
    if (n < 1024) return n + " B";
    if (n < 1048576) return (n / 1024).toFixed(0) + " KB";
    return (n / 1048576).toFixed(1) + " MB";
  };

  const deleteSelected = async () => {
    if (!sel || pickedIds.length === 0 || busy) return;
    if (!(await uiConfirm(`Delete ${pickedIds.length} screenshot${pickedIds.length > 1 ? "s" : ""}? The comment thread${pickedIds.length > 1 ? "s stay" : " stays"} - only the image${pickedIds.length > 1 ? "s are" : " is"} removed.`))) return;
    setBusy(true);
    try {
      const r = await fetch(`/__share_comments?project=${encodeURIComponent(sel.project)}`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ op: "clear_shots", prototype: sel.prototype, commentIds: pickedIds }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "delete failed");
      setPicked({});
      loadComments(sel);
      loadGroups();
    } catch (e) { setDetailErr(String(e.message || e)); }
    finally { setBusy(false); }
  };

  return createPortal(html`
    <div className="newproj-overlay" onClick=${(e) => { if (e.target === e.currentTarget) onClose && onClose(); }}>
      <div className="newproj-card shares-hk-card">
        <header className="newproj-card-head">
          <h2>${sel ? "Screenshots · " + sel.label : "Share housekeeping"}</h2>
          <button className="newproj-close" onClick=${onClose} aria-label="Close">×</button>
        </header>
        <div className="newproj-card-body shares-hk-body">
          ${!sel ? html`
            ${err && html`<div className="shares-error-banner">${err}</div>`}
            ${groups === null && html`<div className="runs-empty">Loading…</div>`}
            ${groups !== null && groups.length === 0 && html`<div className="runs-empty">No shared prototypes with comments yet.</div>`}
            ${groups !== null && groups.length > 0 && html`
              <div className="shares-hk-grouplist">
                ${groups.map(g => html`
                  <button className="shares-hk-grouprow" key=${g.project + "/" + g.prototype} onClick=${() => openGroup(g)}>
                    <div className="shares-hk-grouprow-main">
                      <div className="shares-hk-grouprow-label">
                        ${g.label}${!g.shareExists ? html`<span className="shares-chip">unshared</span>` : ""}
                      </div>
                      <div className="shares-hk-grouprow-sub"><code>${g.project}</code> · <code>source/${g.prototype}/</code></div>
                    </div>
                    <div className="shares-hk-grouprow-stats">
                      <span className="shares-hk-grouprow-imgs" title="comments with a screenshot"><${Icon.Image}/> ${g.withImages}</span>
                      <span className="shares-hk-grouprow-bytes">${fmtBytes(g.imageBytes)}</span>
                      <span className="shares-hk-grouprow-total">${g.totalComments} comment${g.totalComments === 1 ? "" : "s"}</span>
                    </div>
                  </button>
                `)}
              </div>
            `}
          ` : html`
            <div className="shares-hk-detail-toolbar">
              <button className="shares-btn" onClick=${() => { setSel(null); setComments(null); setPicked({}); }}>← Back</button>
              <div className="th-tasks-filter" role="tablist" aria-label="Filter comments">
                ${[["withImages", "With images"], ["open", "Open"], ["done", "Done"], ["archived", "Archived"], ["all", "All"]].map(([k, lbl]) => html`
                  <button key=${k} role="tab" aria-selected=${filter === k}
                    className=${"th-tasks-filter-btn" + (filter === k ? " is-active" : "")}
                    onClick=${() => setFilter(k)}>${lbl}</button>
                `)}
              </div>
              <input className="shares-search" type="search" placeholder="Search comments…" value=${q} onInput=${e => setQ(e.target.value)}/>
            </div>
            ${detailErr && html`<div className="shares-error-banner">${detailErr}</div>`}
            <div className="shares-hk-bulkbar">
              <label className="shares-hk-selall">
                <input type="checkbox" checked=${allChecked} disabled=${withImageVisible.length === 0} onChange=${toggleAll}/>
                Select all images (${withImageVisible.length})
              </label>
              <span style=${{ flex: 1 }}></span>
              <button className="shares-btn shares-btn-danger" disabled=${pickedIds.length === 0 || busy} onClick=${deleteSelected}>
                ${busy ? "Deleting…" : `Delete ${pickedIds.length || ""} image${pickedIds.length === 1 ? "" : "s"}`}
              </button>
            </div>
            ${comments === null && html`<div className="runs-empty">Loading…</div>`}
            ${comments !== null && visible.length === 0 && html`<div className="runs-empty">No comments match this filter.</div>`}
            ${comments !== null && visible.length > 0 && html`
              <table className="shares-hk-table">
                <thead><tr>
                  <th className="shares-hk-col-check"></th><th>Image</th><th>Author</th>
                  <th>Page</th><th>Comment</th><th>When</th><th>Status</th>
                </tr></thead>
                <tbody>
                  ${visible.map(c => html`
                    <tr key=${c.id} className=${c.shot ? "" : "is-noimg"}>
                      <td className="shares-hk-col-check">
                        ${c.shot ? html`<input type="checkbox" checked=${!!picked[c.id]}
                          onChange=${e => setPicked(p => ({ ...p, [c.id]: e.target.checked }))}/>` : ""}
                      </td>
                      <td>${c.shot
                        ? html`<a href=${shotUrl(sel, c)} target="_blank" rel="noopener" className="shares-hk-thumb">
                            <img src=${shotUrl(sel, c)} loading="lazy" alt="Screenshot"/></a>`
                        : html`<span className="shares-hk-noimg">none</span>`}</td>
                      <td>${(c.author && c.author.name) || "Anonymous"}</td>
                      <td className="shares-hk-page" title=${c.page || ""}>${c.page || ""}</td>
                      <td className="shares-hk-text">${(c.text || "").slice(0, 140)}</td>
                      <td className="shares-hk-when">${formatIsoAge(c.createdAt)}</td>
                      <td><span className=${"sv-status-chip " + (c.status || "open")}>${c.status || "open"}</span></td>
                    </tr>
                  `)}
                </tbody>
              </table>
            `}
          `}
        </div>
      </div>
    </div>
  `, document.body);
}

/* GitHubAccountButton - landing-page (top-right) GitHub account control. Sign-in
   is HOST-level and shared with the in-editor Git panel, so connecting here also
   lights up Pull/Push there. Reuses /__github/status + the device-flow / paste-
   token sign-in endpoints. Self-contained: polls status, owns a little popover. */
function GitHubAccountButton() {
  const [gh, setGh] = useState(null);          // {configured, signedIn, login, avatar}
  const [open, setOpen] = useState(false);
  const [device, setDevice] = useState(null);  // active device-flow {user_code, verification_uri, …}
  const [tokenInput, setTokenInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState(null);
  const wrapRef = useRef(null);
  const devTimer = useRef(0);

  const loadGh = useCallback(() => {
    fetch(apiUrl("/__github/status"))
      .then(r => (r.ok ? r.json() : null))
      .then(j => setGh(j || {}))
      .catch(() => setGh({}));
  }, []);
  useEffect(() => {
    loadGh();
    const t = setInterval(loadGh, 10000);
    return () => { clearInterval(t); if (devTimer.current) clearTimeout(devTimer.current); };
  }, [loadGh]);
  useEffect(() => {
    if (!open) return;
    const onDown = (e) => { if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [open]);

  const flash = (m) => { setNote(String(m)); setTimeout(() => setNote(null), 3500); };
  const ghOp = async (kind, body) => {
    setBusy(true);
    try {
      const r = await fetch(apiUrl("/__github/" + kind), {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body || {}) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || (kind + " failed"));
      return j;
    } catch (e) { flash(e.message || e); return null; }
    finally { setBusy(false); }
  };
  const pollDevice = (interval) => {
    devTimer.current = setTimeout(async () => {
      try {
        const r = await fetch(apiUrl("/__github/device/poll"), {
          method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" });
        const j = await r.json().catch(() => ({}));
        if (j.status === "ok") { setDevice(null); flash("Signed in as " + j.login); loadGh(); return; }
        if (j.status === "pending") { pollDevice(j.slowDown ? interval + 5 : interval); return; }
        flash(j.error || "authorization failed"); setDevice(null);
      } catch (e) { flash(e.message || e); setDevice(null); }
    }, Math.max(2, interval) * 1000);
  };
  const startDevice = async () => { const j = await ghOp("device/start", {}); if (j) { setDevice(j); pollDevice(j.interval || 5); } };
  const cancelDevice = () => { if (devTimer.current) { clearTimeout(devTimer.current); devTimer.current = 0; } setDevice(null); };
  const doTokenSignin = async () => { const t = tokenInput.trim(); if (!t) return; const j = await ghOp("token", { token: t }); if (j) { setTokenInput(""); flash("Signed in as " + j.login); loadGh(); } };
  const signOut = async () => { if (devTimer.current) clearTimeout(devTimer.current); const j = await ghOp("signout", {}); if (j) { setDevice(null); flash("Signed out"); loadGh(); } };

  const signedIn = !!(gh && gh.signedIn);
  return html`
    <div className="landing-gh" ref=${wrapRef}>
      <button className=${"landing-gh-btn" + (signedIn ? " is-in" : "")} onClick=${() => setOpen(o => !o)}
        title=${signedIn ? ("GitHub: " + (gh.login || "signed in")) : "Connect a GitHub account"}>
        ${signedIn && gh.avatar
          ? html`<img className="landing-gh-avatar" src=${gh.avatar} alt="" />`
          : html`<${Icon.Fork}/>`}
        <span className="landing-gh-label">${signedIn ? (gh.login || "GitHub") : "Connect GitHub"}</span>
        <${Icon.Chev}/>
      </button>
      ${open && html`
        <div className="popover landing-gh-pop">
          ${note && html`<div className="landing-gh-note">${note}</div>`}
          ${signedIn ? html`
            <div className="popover-title">GitHub account</div>
            <div className="landing-gh-who">
              ${gh.avatar ? html`<img className="landing-gh-avatar" src=${gh.avatar} alt="" />` : html`<${Icon.User}/>`}
              <span>${gh.login || "signed in"}</span>
            </div>
            <button className="popover-item" onClick=${signOut} disabled=${busy}>
              <span className="popover-item-icon"><${Icon.X}/></span><span>Sign out</span></button>
          ` : (device ? html`
            <div className="popover-title">Authorize on GitHub</div>
            <div className="landing-gh-code">${device.user_code}</div>
            <button className="popover-item" onClick=${() => window.open(device.verification_uri || "https://github.com/login/device", "_blank")}>
              <span className="popover-item-icon"><${Icon.External}/></span><span>Open GitHub & enter the code</span></button>
            <button className="popover-item" onClick=${cancelDevice}>
              <span className="popover-item-icon"><${Icon.X}/></span><span>Cancel</span></button>
            <div className="landing-gh-hint">Waiting for authorization… keep this open.</div>
          ` : html`
            <div className="popover-title">Connect GitHub</div>
            <input className="landing-gh-input" type="password" placeholder="Paste a token (scope: repo)"
              value=${tokenInput} onInput=${e => setTokenInput(e.target.value)}
              onKeyDown=${e => { if (e.key === "Enter") doTokenSignin(); }} />
            <button className="popover-item is-primary" onClick=${doTokenSignin} disabled=${busy || !tokenInput.trim()}>
              <span className="popover-item-icon"><${Icon.Check}/></span><span>${busy ? "Connecting…" : "Connect with token"}</span></button>
            <a className="landing-gh-link" href="https://github.com/settings/tokens/new?scopes=repo&description=Woven" target="_blank" rel="noopener">Create a token →</a>
            <button className="popover-item" onClick=${startDevice} disabled=${busy}>
              <span className="popover-item-icon"><${Icon.External}/></span><span>Sign in with a code instead</span></button>
          `)}
        </div>
      `}
    </div>
  `;
}

/* CloneFromGithubDialog - "New project ▸ From GitHub". Lists the signed-in
   account's repos (picker only), lets the user confirm/edit the project name,
   then POSTs /__projects/clone to clone the repo into a fresh project folder.
   Because the new project IS the clone, origin is set and Pull/Push work with no
   "dirty tree" trap. Reuses the New-project wizard's overlay/card classes. */
function CloneFromGithubDialog({ onClose, onCreated }) {
  const [gh, setGh] = useState(null);
  const [repos, setRepos] = useState(null);     // null = loading
  const [query, setQuery] = useState("");
  const [picked, setPicked] = useState(null);   // selected repo
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);
  const searchTimer = useRef(0);

  const loadGh = useCallback(() => {
    fetch(apiUrl("/__github/status")).then(r => r.ok ? r.json() : null).then(j => setGh(j || {})).catch(() => setGh({}));
  }, []);
  const fetchRepos = useCallback(async (q) => {
    setRepos(null);
    try {
      const base = apiUrl("/__github/repos");
      const url = q ? base + (base.includes("?") ? "&" : "?") + "q=" + encodeURIComponent(q) : base;
      const r = await fetch(url);
      const j = await r.json().catch(() => ({}));
      setRepos(j.repos || []);
    } catch { setRepos([]); }
  }, []);
  useEffect(() => { loadGh(); }, [loadGh]);
  useEffect(() => { if (gh && gh.signedIn) fetchRepos(""); }, [gh, fetchRepos]);

  const onSearch = (v) => {
    setQuery(v);
    if (searchTimer.current) clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(() => fetchRepos(v.trim()), 320);
  };
  const slug = (s) => (s || "").replace(/\.git$/, "").replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[-._]+|[-._]+$/g, "").slice(0, 64) || "project";
  const choose = (r) => { setPicked(r); setName(slug(r.name || (r.full_name || "").split("/").pop())); setErr(null); };
  const create = async () => {
    if (!picked) return;
    setBusy(true); setErr(null);
    try {
      const r = await fetch(apiUrl("/__projects/clone"), {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ clone_url: picked.clone_url, id: name.trim() || undefined }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "clone failed");
      onCreated && onCreated({ id: j.id });
    } catch (e) { setErr(e.message || String(e)); }
    finally { setBusy(false); }
  };

  const signedIn = !!(gh && gh.signedIn);
  return createPortal(html`
    <div className="newproj-overlay" onClick=${(e) => { if (e.target === e.currentTarget) onClose && onClose(); }}>
      <div className="newproj-card clone-card">
        <header className="newproj-card-head">
          <h2>New project from GitHub</h2>
          <button type="button" className="newproj-close" onClick=${onClose} aria-label="Close">×</button>
        </header>
        <div className="newproj-card-body">
          ${err && html`<div className="newproj-error">${err}</div>`}
          ${!signedIn ? html`
            <div className="clone-signin-note">
              <b>Connect your GitHub account first.</b>
              <div className="newproj-hint">Use the <b>Connect GitHub</b> button at the top-right of the landing page, then come back.</div>
              <button className="newproj-cancel" onClick=${loadGh}>Recheck</button>
            </div>
          ` : (!picked ? html`
            <input className="clone-search" placeholder="Search your repositories…" value=${query}
              onInput=${e => onSearch(e.target.value)} autoFocus spellCheck="false" />
            ${repos === null && html`<div className="clone-empty">Loading repos…</div>`}
            ${repos !== null && repos.length === 0 && html`<div className="clone-empty">No repositories found${query ? " for that search" : ""}.</div>`}
            <div className="clone-repo-list">
              ${(repos || []).map(r => html`
                <button className="clone-repo-item" key=${r.full_name} onClick=${() => choose(r)}>
                  <span className="clone-repo-name">${r.full_name}</span>
                  ${r.private && html`<span className="clone-pill">private</span>`}
                </button>`)}
            </div>
          ` : html`
            <div className="clone-picked">
              <span className="clone-repo-name">${picked.full_name}</span>
              ${picked.private && html`<span className="clone-pill">private</span>`}
              <button className="newproj-link" onClick=${() => setPicked(null)}>Change</button>
            </div>
            <label className="newproj-field">
              <input value=${name} onInput=${e => setName(e.target.value)} placeholder="Project name"
                maxLength=${64} onKeyDown=${e => { if (e.key === "Enter") create(); }} autoFocus />
            </label>
            <div className="newproj-hintrow"><span className="newproj-hint">Cloned into a fresh project folder - Pull & Push work right away.</span></div>
          `)}
        </div>
        ${signedIn && picked && html`
          <footer className="newproj-card-foot">
            <button type="button" className="newproj-cancel" onClick=${onClose} disabled=${busy}>Cancel</button>
            <button type="button" className="newproj-create" disabled=${busy || !name.trim()} onClick=${create}>
              ${busy ? "Cloning…" : "Clone & create"}</button>
          </footer>
        `}
      </div>
    </div>
  `, document.body);
}

// Housekeeping - permanent bulk-delete of soft-deleted projects. Project delete
// (_project_delete) only MOVES a project to projects/.trash/; nothing else ever
// empties it. This panel lists those trash entries and hard-deletes the selected
// ones - the only forever-delete path in the product.
function ProjectsHousekeeping({ onClose }) {
  const [items, setItems] = useState(null);          // null = loading
  const [sel, setSel] = useState(() => new Set());   // selected trash-folder names
  const [err, setErr] = useState(null);
  const [purging, setPurging] = useState(false);

  const load = useCallback(() => {
    setItems(null); setErr(null); setSel(new Set());
    fetch("/__projects/trash")
      .then(r => r.ok ? r.json() : Promise.reject(new Error("HTTP " + r.status)))
      .then(j => setItems(j.items || []))
      .catch(e => { setErr(e.message || String(e)); setItems([]); });
  }, []);
  useEffect(() => { load(); }, [load]);

  const fmtSize = (b) => {
    if (!b) return "0 B";
    const u = ["B", "KB", "MB", "GB", "TB"]; let i = 0, n = b;
    while (n >= 1024 && i < u.length - 1) { n /= 1024; i++; }
    return (i === 0 ? n : n.toFixed(1)) + " " + u[i];
  };
  const fmtWhen = (iso) => { if (!iso) return "-"; try { return new Date(iso).toLocaleString(); } catch { return iso; } };

  const list = items || [];
  const toggle = (name) => setSel(s => { const n = new Set(s); n.has(name) ? n.delete(name) : n.add(name); return n; });
  const allSelected = list.length > 0 && list.every(it => sel.has(it.name));
  const toggleAll = () => setSel(allSelected ? new Set() : new Set(list.map(it => it.name)));
  const selectedItems = list.filter(it => sel.has(it.name));
  const totalSel = selectedItems.reduce((a, it) => a + (it.sizeBytes || 0), 0);

  const purge = async () => {
    const names = selectedItems.map(it => it.name);
    if (!names.length) return;
    const ok = await uiConfirm(
      `Permanently delete ${names.length} project${names.length > 1 ? "s" : ""} (${fmtSize(totalSel)})?\n\n` +
      `This removes the files from disk for good - it cannot be undone.`
    );
    if (!ok) return;
    setPurging(true); setErr(null);
    try {
      const r = await fetch("/__projects/trash/purge", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ names }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "HTTP " + r.status);
      load();
      if ((j.errors || []).length) setErr(`${j.errors.length} entr${j.errors.length > 1 ? "ies" : "y"} couldn't be deleted.`);
    } catch (e) {
      setErr(e.message || String(e));
    } finally {
      setPurging(false);
    }
  };

  return html`
    <div className="newproj-overlay" onClick=${(e) => { if (e.target === e.currentTarget) onClose && onClose(); }}>
      <div className="newproj-card hk-card">
        <header className="newproj-card-head">
          <h2>Housekeeping</h2>
          <button className="newproj-close" onClick=${onClose} aria-label="Close">×</button>
        </header>
        <div className="newproj-card-body hk-body">
          <p className="hk-intro">Deleted projects are moved to <code>.trash/</code> and kept until you remove them here. Permanent delete cannot be undone.</p>
          ${err && html`<div className="shares-error-banner">${err}</div>`}
          ${items === null
            ? html`<div className="runs-empty">Loading…</div>`
            : list.length === 0
              ? html`<div className="runs-empty">Trash is empty - nothing to clean up.</div>`
              : html`
                <table className="hk-table">
                  <thead><tr>
                    <th className="hk-col-check"><input type="checkbox" checked=${allSelected} onChange=${toggleAll} aria-label="Select all"/></th>
                    <th>Project</th><th>Deleted</th><th className="hk-col-size">Size</th>
                  </tr></thead>
                  <tbody>
                    ${list.map(it => html`
                      <tr key=${it.name} data-sel=${sel.has(it.name)} onClick=${() => toggle(it.name)}>
                        <td className="hk-col-check"><input type="checkbox" checked=${sel.has(it.name)} onChange=${() => toggle(it.name)} onClick=${e => e.stopPropagation()} aria-label=${"Select " + it.projectId}/></td>
                        <td><span className="hk-pid">${it.projectId}</span></td>
                        <td className="hk-when">${fmtWhen(it.deletedAt)}</td>
                        <td className="hk-col-size">${fmtSize(it.sizeBytes)}</td>
                      </tr>
                    `)}
                  </tbody>
                </table>
              `}
        </div>
        <footer className="newproj-card-foot hk-foot">
          <span className="hk-foot-info">${sel.size} selected${sel.size ? " · " + fmtSize(totalSel) : ""}</span>
          <div className="hk-foot-actions">
            <button className="tbtn" onClick=${onClose}>Close</button>
            <button className="tbtn tbtn-danger" disabled=${!sel.size || purging} onClick=${purge}>
              ${purging ? "Deleting…" : "Delete permanently"}
            </button>
          </div>
        </footer>
      </div>
    </div>
  `;
}

function ProjectsLanding({ info, projects, onReload }) {
  const [creating, setCreating] = useState(false);
  const [cloningGithub, setCloningGithub] = useState(false);  // "From GitHub" dialog
  const [newMenuOpen, setNewMenuOpen] = useState(false);       // New-project split dropdown
  const newMenuRef = useRef(null);
  const [editingId, setEditingId] = useState(null);
  const [editLabel, setEditLabel] = useState("");
  const [busyId, setBusyId] = useState(null);
  const [err, setErr] = useState(null);
  const [filter, setFilter] = useState("");
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [housekeepingOpen, setHousekeepingOpen] = useState(false);
  // v3.3 - Top-level landing tabs. "projects" is the legacy default; "orchestrators"
  // surfaces the orchestrator registry (per .claude/agents/*.manifest.json).
  const [activeTab, setActiveTab] = useState("projects");
  // Share mode - count for the Shares tab chip. Seeded once on mount;
  // SharesLanding keeps it fresh while that tab is open (onCountChange).
  const [shareCount, setShareCount] = useState(null);
  useEffect(() => {
    fetch("/__shares").then((r) => (r.ok ? r.json() : null))
      .then((j) => { if (j) setShareCount((j.shares || []).filter(s => !s.liveOnly).length); })
      .catch(() => {});
  }, []);

  // v3.13 - Workspace SYSTEM AGENT threads, lifted to the landing root so the
  // shared Bot icon button in the title row and both System-tab section
  // "Add" buttons drive ONE drawer + thread list (threads are shared across
  // Orchestrators + Design library). See the SystemThreadsPanel→intake
  // redesign block above for the rationale.
  const [systemThreads, setSystemThreads] = useState([]);
  const [systemRun, setSystemRun] = useState(null);
  const [systemPermMode, setSystemPermMode] = useState("bypassPermissions");
  const fetchSystemThreads = useCallback(() => {
    fetch("/__system_runs").then(r => r.ok ? r.json() : null)
      .then(j => setSystemThreads(j ? (j.runs || []) : []))
      .catch(() => {});
  }, []);
  useEffect(() => { fetchSystemThreads(); }, [fetchSystemThreads]);
  useEffect(() => {
    const h = () => fetchSystemThreads();
    window.addEventListener("th:system-changed", h);
    return () => window.removeEventListener("th:system-changed", h);
  }, [fetchSystemThreads]);
  // POST the composed intake brief straight to /__run (scope=system); the
  // daemon spawns the system agent and feeds the brief as its first message,
  // so the drawer opens on a LIVE run already streaming the agent's plan -
  // no isNew shell, no re-typing.
  const spawnSystemThread = useCallback(async ({ section, prompt, title }) => {
    const res = await fetch("/__run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        scope: "system", section, prompt, title,
        agentId: "claude", kind: "freeform", permissionMode: systemPermMode,
      }),
    });
    let body = null;
    try { body = await res.json(); } catch {}
    if (!res.ok) throw new Error((body && (body.error || body.hint)) || `HTTP ${res.status}`);
    setSystemRun(body);
    fetchSystemThreads();
    return body;
  }, [systemPermMode, fetchSystemThreads]);
  const openSystemThread = useCallback((run) => { setSystemRun(run); }, []);
  const onSystemRunComplete = useCallback(() => {
    fetchSystemThreads();
    // v3.13 - always re-pull the System registries when a system thread
    // turn ends. The Write/Edit detector misses files the agent creates via
    // Bash (cat >, cp, mkdir), and a system thread's whole purpose is to
    // mutate the harness, so refetch unconditionally - the endpoints are
    // cheap GETs and each re-reads disk per request.
    try { window.dispatchEvent(new CustomEvent("th:system-changed")); } catch {}
  }, [fetchSystemThreads]);
  const mediaCfg = useMediaConfig();
  // v3.4.41 - Required local skills (rembg). The setup card stays open
  // until every required skill is installed, even after the model is
  // configured - that way users who set up an API key but skipped rembg
  // still get nudged before they hit the cutout stage of an asset run.
  const localSkills = useRequiredLocalSkills();
  const setupNeeded = !mediaCfg.configured || !localSkills.allRequiredInstalled;
  const onboardingReady = mediaCfg.loaded && localSkills.loaded;
  // v3.4.46 - Once the wizard mounts, keep it mounted until the user
  // explicitly acknowledges completion (clicks "Got it" on the final
  // "✓ All set!" view). Without this, the moment the rembg install
  // succeeded the gate flipped and the wizard silently unmounted -
  // looked like a glitch, no celebration. The card now shows a clear
  // success state and waits for the user to dismiss it.
  // v3.4.48 - wasNeededRef starts at false, NOT at the initial setupNeeded
  // value. Pre-fix: on every page reload, the first render saw mediaCfg
  // and localSkills as un-loaded → setupNeeded = !undefined = true →
  // wasNeededRef captured true → after fetches resolved (setupNeeded → false),
  // the wizard still opened because wasNeededRef.current was already true.
  // Now we only flip the ref when onboardingReady AND setupNeeded - the
  // post-fetch confirmation of an actual missing requirement.
  const [setupAcknowledged, setSetupAcknowledged] = useState(false);
  const wasNeededRef = useRef(false);
  useEffect(() => {
    if (onboardingReady && setupNeeded) {
      wasNeededRef.current = true;
      // If something regresses (e.g. user revokes a key) re-show the wizard.
      if (setupAcknowledged) setSetupAcknowledged(false);
    }
  }, [onboardingReady, setupNeeded, setupAcknowledged]);
  // Show the wizard while there's something to do, OR while we're showing
  // the post-completion "All set!" state that the user hasn't dismissed yet.
  const wizardOpen = setupNeeded || (wasNeededRef.current && !setupAcknowledged);
  // True exactly when the onboarding setup card (ModelSetupCard) is on screen.
  // Reused to keep the Housekeeping trigger off the first-run / setup view.
  const onboardingCardShowing = projects.length === 0 && !creating && wizardOpen && onboardingReady;
  // Workspace DS list - needed for the wizard's "Pick from workspace" path.
  // Lazy-fetched only when the wizard opens (cheap GET, but no need to spam
  // the daemon on every landing render).
  const [dsList, setDsList] = useState([]);
  useEffect(() => {
    if (!creating) return;
    fetch(apiUrl("/__design_system"))
      .then(r => r.ok ? r.json() : { items: [] })
      .then(j => setDsList(j.items || []))
      .catch(() => setDsList([]));
  }, [creating]);

  const openProject = (pid, view) => {
    const url = new URL(window.location.href);
    url.searchParams.set("project", pid);
    url.searchParams.delete("prototype");
    url.searchParams.delete("branch");
    if (view) url.searchParams.set("view", view);
    else url.searchParams.delete("view");
    thNavigate(url.toString());
  };

  const onWizardCreated = ({ id }) => {
    setCreating(false);
    // v3.1 - Every fresh project lands in workflow mode. The editor mode is
    // for navigating an EXISTING source/ tree; a brand-new project has no
    // pages yet, so landing in editor mode just shows a "missing index.html"
    // error and confuses the user. Workflow mode is the right starting
    // surface - the user assembles the project there before any HTML exists.
    openProject(id, "workflow");
  };
  // A cloned-from-GitHub project DOES have a source/ tree already, but we still
  // land in workflow mode for consistency with the wizard flow.
  const onClonedCreated = ({ id }) => { setCloningGithub(false); openProject(id, "workflow"); };
  // Close the New-project split dropdown on any outside click.
  useEffect(() => {
    if (!newMenuOpen) return;
    const onDown = (e) => { if (newMenuRef.current && !newMenuRef.current.contains(e.target)) setNewMenuOpen(false); };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [newMenuOpen]);

  const saveRename = async (pid) => {
    setErr(null);
    const label = (editLabel || "").trim();
    if (!label) { setErr("label required"); return; }
    setBusyId(pid);
    try {
      const r = await fetch(apiUrl("/__projects/rename"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: pid, label }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
      await onReload();
      setEditingId(null);
      setEditLabel("");
    } catch (e) {
      setErr(e.message || String(e));
    } finally {
      setBusyId(null);
    }
  };

  const duplicateProject = async (pid, label) => {
    // Local copy - no LLM. Server clones the tree and rewrites every reference
    // to the old project name (id slug + meta.project label) to the new one.
    const suggested = (label || pid) + " copy";
    const newLabel = await uiPrompt(`Duplicate "${label || pid}" as:`, suggested);
    if (newLabel === null) return;            // user cancelled
    const trimmed = newLabel.trim();
    if (!trimmed) { setErr("label required"); return; }
    setErr(null);
    setBusyId(pid);
    try {
      const r = await fetch(apiUrl("/__projects/duplicate"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: pid, label: trimmed }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
      await onReload();
    } catch (e) {
      setErr(e.message || String(e));
    } finally {
      setBusyId(null);
    }
  };

  const deleteProject = async (pid, label) => {
    if (!(await uiConfirm(`Delete project "${label || pid}"?\n\nMoved to .trash/${pid}-<timestamp>/ inside the workspace - recoverable, not hard-deleted.`))) return;
    setErr(null);
    setBusyId(pid);
    try {
      const r = await fetch(apiUrl("/__projects/delete"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: pid }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
      await onReload();
    } catch (e) {
      setErr(e.message || String(e));
    } finally {
      setBusyId(null);
    }
  };

  const fmtActivity = (iso) => {
    if (!iso) return "-";
    const then = new Date(iso);
    const now = new Date();
    const ms = now - then;
    const s = Math.floor(ms / 1000);
    if (s < 60) return "just now";
    const m = Math.floor(s / 60);
    if (m < 60) return `${m}m ago`;
    const h = Math.floor(m / 60);
    if (h < 24) return `${h}h ago`;
    const d = Math.floor(h / 24);
    if (d < 7) return `${d}d ago`;
    return then.toLocaleDateString();
  };

  // v3.6 - Sort by lastActivity descending so the most recently touched
  // project lands on top. Projects with no activity stamp sink to the bottom
  // (Date.parse → NaN → 0). Tie-break on id for stable rendering.
  const sorted = [...projects].sort((a, b) => {
    const ta = a && a.lastActivity ? Date.parse(a.lastActivity) || 0 : 0;
    const tb = b && b.lastActivity ? Date.parse(b.lastActivity) || 0 : 0;
    if (tb !== ta) return tb - ta;
    return (a.id || "").localeCompare(b.id || "");
  });
  const filtered = filter
    ? sorted.filter(p => {
        const q = filter.toLowerCase();
        return (p.id || "").toLowerCase().includes(q) || (p.label || "").toLowerCase().includes(q);
      })
    : sorted;

  // ──────────────────────────────────────────────────────────────────────────
  // Mount the landing's diamond-field shader on a single full-page canvas
  // behind the whole landing. The shader draws ONE uniform light diamond field
  // top to bottom - the header is a frosted-glass element over it (no dark band,
  // no teeth). The disposer returned by mountShader stops the RAF + frees the GL
  // context the moment the user enters a project (this component unmounts).
  // ──────────────────────────────────────────────────────────────────────────
  const bgCanvasRef = useRef(null);
  useEffect(() => {
    if (!bgCanvasRef.current || typeof window.mountShader !== "function") return;
    const disposeBg = window.mountShader(bgCanvasRef.current, window.SHADER_BG, {
      track: window,
    });
    return () => { if (disposeBg) disposeBg(); };
  }, []);

  // Cursor-reveal for the dot field. The whole landing is plain white; the dot
  // lattice (.landing-root::before) is masked by a radial gradient centred on
  // the pointer, so the dots only bloom in a soft radius around the cursor.
  // We publish the pointer position as --landing-mx/--landing-my (viewport px -
  // .landing-root is position:fixed inset:0, so clientX/Y map straight onto it)
  // and toggle .is-cursor-active to fade the field in/out as the pointer enters
  // and leaves the window.
  useEffect(() => {
    const root = document.querySelector(".landing-root");
    if (!root) return;
    let raf = 0, px = 0, py = 0;
    const apply = () => {
      raf = 0;
      root.style.setProperty("--landing-mx", px + "px");
      root.style.setProperty("--landing-my", py + "px");
    };
    const onMove = (e) => {
      px = e.clientX; py = e.clientY;
      if (!root.classList.contains("is-cursor-active")) root.classList.add("is-cursor-active");
      if (!raf) raf = requestAnimationFrame(apply);
    };
    const onLeave = (e) => {
      // Only fade out when the pointer actually leaves the window, not when it
      // crosses between child elements (relatedTarget null === left the page).
      if (!e.relatedTarget) root.classList.remove("is-cursor-active");
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    document.addEventListener("pointerout", onLeave);
    return () => {
      window.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerout", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // The black header is taken out of flow (position: absolute, pinned top), so
  // the scrolling cards pass behind it. .landing-main therefore needs a top
  // padding equal to the live header height so its content starts just below the
  // header instead of under it. We publish that height as the CSS var
  // `--landing-header-h` and keep it in sync whenever the header height changes
  // (different tab, viewport resize, load).
  useEffect(() => {
    const root = document.querySelector(".landing-root");
    const header = document.querySelector(".landing-header");
    if (!root || !header) return;
    const update = () => {
      root.style.setProperty("--landing-header-h", header.offsetHeight + "px");
    };
    update();
    if (typeof ResizeObserver !== "undefined") {
      const ro = new ResizeObserver(update);
      ro.observe(header);
      window.addEventListener("resize", update);
      return () => {
        ro.disconnect();
        window.removeEventListener("resize", update);
      };
    }
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, [activeTab, projects.length]);

// v3.5.x - Starred-list scroll affordance manager. Each .landing-card-stars-
  // list element needs:
  //   • .is-scrollable class when scrollHeight > clientHeight (drives the
  //     fade-at-bottom mask + flips overflow to auto so wheel works)
  //   • .at-bottom class when scrolled to the end (drops the mask AND drops
  //     overscroll-behavior so further wheel scrolls the PAGE not the list)
  // Without this the default overflow:auto would intercept wheel events on
  // single-item lists (nothing to scroll, but wheel still consumed) and the
  // mask would hide the final item when the user is already at the end.
  useEffect(() => {
    const lists = document.querySelectorAll(".landing-card-stars-list");
    if (!lists.length) return;
    const cleanups = [];
    lists.forEach((list) => {
      const update = () => {
        // `is-multiple` → 2+ starred prototypes. Drives the visible fade
        // overlay + the ::after scroll-spacer + overflow:auto. Single-
        // item lists stay clean: no scroll capture, no fade.
        // `at-top` / `at-bottom` → toggle overscroll-behavior so wheel
        // events bubble to the page at the list's boundaries.
        const items = list.querySelectorAll("li").length;
        const multiple = items > 1;
        const atTop = multiple && list.scrollTop <= 1;
        const atBottom = multiple && (list.scrollTop + list.clientHeight >= list.scrollHeight - 2);
        list.classList.toggle("is-multiple", multiple);
        list.classList.toggle("at-top", atTop);
        list.classList.toggle("at-bottom", atBottom);
      };
      update();
      list.addEventListener("scroll", update, { passive: true });
      let ro = null;
      if (typeof ResizeObserver !== "undefined") {
        ro = new ResizeObserver(update);
        ro.observe(list);
      }
      cleanups.push(() => {
        list.removeEventListener("scroll", update);
        if (ro) ro.disconnect();
      });
    });
    return () => cleanups.forEach((fn) => fn());
  }, [projects.length, filter, activeTab]);

  return html`
    <div className="landing-root">
      <header className="landing-header">
        <div className="landing-header-inner">
          <div className="landing-brandrow">
            <span className="landing-brand">
              <svg className="landing-logo-mark" viewBox="0 0 76 40" aria-hidden="true">
                <path d="M14 2L26 14L14 26L2 14Z"/>
                <path d="M38 2L50 14L38 26L26 14Z"/>
                <path d="M62 2L74 14L62 26L50 14Z"/>
                <path d="M26 14L38 26L26 38L14 26Z"/>
                <path d="M50 14L62 26L50 38L38 26Z"/>
              </svg>
              <span className="landing-brand-name">Woven</span>
            </span>
            <div className="landing-meta">
              <span className="landing-meta-label">Workspace</span>
              <code className="landing-meta-path">${info.workspaceDir}</code>
              <${DaemonIndicator}/>
              <${CliIndicator}/>
              <${ModelStatusIndicator} onOpenSettings=${() => setSettingsOpen(true)}/>
              <${GitHubAccountButton}/>
              <${SettingsGearButton} onClick=${() => setSettingsOpen(true)} className="landing-gear"/>
            </div>
          </div>
          <div className="landing-titlebar">
            <div className="landing-tabs">
              <button
                className=${"landing-tab" + (activeTab === "projects" ? " is-active" : "")}
                onClick=${() => setActiveTab("projects")}
                aria-pressed=${activeTab === "projects"}
              >
                <span className="landing-tab-label">Projects</span>
                <span className="landing-tab-count">${projects.length}</span>
              </button>
              <button
                className=${"landing-tab" + (activeTab === "shares" ? " is-active" : "")}
                onClick=${() => setActiveTab("shares")}
                aria-pressed=${activeTab === "shares"}
                title="Shared prototypes - live Cloudflare tunnels, links, and review comments."
              >
                <span className="landing-tab-label">Shares</span>
                ${shareCount != null && shareCount > 0 && html`<span className="landing-tab-count">${shareCount}</span>`}
              </button>
              <button
                className=${"landing-tab" + (activeTab === "system" ? " is-active" : "")}
                onClick=${() => setActiveTab("system")}
                aria-pressed=${activeTab === "system"}
                title="Capabilities - orchestrators, skills, subagents, and node kinds the app ships."
              >
                <span className="landing-tab-label">Capabilities</span>
              </button>
            </div>
            <div className="landing-titlebar-right">
              ${systemThreads.length > 0 && html`<${SystemAgentThreadButton} threads=${systemThreads} onOpen=${openSystemThread}/>`}
              ${activeTab === "projects" && html`
              <div className="landing-actions">
                ${projects.length > 0 && html`
                  <input
                    className="landing-filter"
                    placeholder="Filter by id or label…"
                    value=${filter}
                    onInput=${e => setFilter(e.target.value)}
                  />
                `}
                <div className="landing-new-split" ref=${newMenuRef}>
                  <button
                    className="landing-new-btn"
                    disabled=${setupNeeded}
                    data-disabled=${setupNeeded}
                    title=${
                      !mediaCfg.configured
                        ? "Connect a model first - see the setup card below."
                        : (!localSkills.allRequiredInstalled
                            ? `Install ${localSkills.missing.map(p => p.label).join(", ")} first - see the setup card below.`
                            : "Create a new project")
                    }
                    onClick=${() => { if (setupNeeded) return; setNewMenuOpen(false); setCreating(true); setErr(null); }}>
                    <span style=${{ fontSize: 16, lineHeight: 1 }}>+</span>
                    <span>New project</span>
                  </button>
                  <button
                    className="landing-new-caret"
                    disabled=${setupNeeded}
                    data-disabled=${setupNeeded}
                    aria-label="More project options"
                    title="More ways to create a project"
                    onClick=${() => { if (setupNeeded) return; setNewMenuOpen(o => !o); }}>
                    <${Icon.Chev}/>
                  </button>
                  ${newMenuOpen && html`
                    <div className="popover landing-new-menu">
                      <button className="popover-item" onClick=${() => { setNewMenuOpen(false); setCreating(true); setErr(null); }}>
                        <span className="popover-item-icon"><${Icon.Plus}/></span><span>Blank project</span></button>
                      <button className="popover-item" onClick=${() => { setNewMenuOpen(false); setCloningGithub(true); setErr(null); }}>
                        <span className="popover-item-icon"><${Icon.Fork}/></span><span>From GitHub…</span></button>
                    </div>
                  `}
                </div>
              </div>
            `}
            </div>
          </div>
        </div>
      </header>
      ${settingsOpen && html`<${WorkflowSettingsDialog} onClose=${() => setSettingsOpen(false)}/>`}
      ${systemRun && createPortal(html`<${ChatDrawer}
        run=${systemRun}
        variant="system"
        onClose=${() => { setSystemRun(null); fetchSystemThreads(); }}
        onStop=${() => {}}
        onRunComplete=${onSystemRunComplete}
        onStatusChange=${() => {}}
        permissionMode=${systemPermMode}
        onPermissionModeChange=${setSystemPermMode}
        onStartNewChat=${(text) => spawnSystemThread({ section: (systemRun && systemRun.section) || "orchestrators", prompt: text, title: text.slice(0, 60) })}
      />`, document.body)}
      <main className="landing-main">
        <div className="landing-main-inner">

        ${activeTab === "shares" && html`<${SharesLanding} onCountChange=${setShareCount}/>`}
        ${activeTab === "system" && html`<${SystemLanding} onSpawnSystemThread=${spawnSystemThread}/>`}

        ${activeTab === "projects" && creating && html`<${NewProjectWizard}
          workspaceProjects=${projects}
          onClose=${() => { setCreating(false); setErr(null); }}
          onCreated=${onWizardCreated}
        />`}

        ${activeTab === "projects" && cloningGithub && html`<${CloneFromGithubDialog}
          onClose=${() => { setCloningGithub(false); setErr(null); }}
          onCreated=${onClonedCreated}
        />`}

        ${activeTab === "projects" && onboardingCardShowing && html`
          <${ModelSetupCard}
            mediaCfg=${mediaCfg}
            localSkills=${localSkills}
            onRefresh=${() => {
              // v3.4.50 - Dispatch BOTH change events so every consumer of
              // useMediaConfig / useAgents re-polls - including the top-right
              // "NO MODEL CONFIGURED" pill (its own useMediaConfig instance)
              // and the CLI pill (its own useAgents instance). Just calling
              // mediaCfg.reload() only refreshed the wizard's local instance
              // and left the indicators stale.
              mediaCfg.reload();
              try { window.dispatchEvent(new CustomEvent("th:media-config-changed")); } catch {}
              try { window.dispatchEvent(new CustomEvent("th:agents-changed")); } catch {}
            }}
            onAcknowledge=${() => setSetupAcknowledged(true)}/>
        `}

        ${activeTab === "projects" && projects.length === 0 && !creating && !setupNeeded && !wizardOpen && html`
          <div className="landing-empty">
            <div className="landing-empty-icon">▣</div>
            <div className="landing-empty-title">No projects yet</div>
            <div className="landing-empty-desc">
              Create your first project to get started. Projects live as folders under
              <code> ${info.workspaceDir}</code> and each one is independently editable.
            </div>
            <button className="landing-new-btn" onClick=${() => { setCreating(true); setErr(null); }}>
              <span style=${{ fontSize: 16, lineHeight: 1 }}>+</span>
              <span>Create your first project</span>
            </button>
          </div>
        `}

        ${activeTab === "projects" && projects.length > 0 && html`
          <div className="landing-grid">
            ${filtered.map(p => editingId === p.id ? html`
              <div key=${p.id} className="landing-card landing-card-editing">
                <div className="landing-card-id">${p.id}</div>
                <label className="landing-field">
                  <span className="landing-field-label">label</span>
                  <input
                    className="landing-input"
                    value=${editLabel}
                    onInput=${e => setEditLabel(e.target.value)}
                    onKeyDown=${e => { if (e.key === "Enter") saveRename(p.id); if (e.key === "Escape") { setEditingId(null); setEditLabel(""); setErr(null); } }}
                    autoFocus
                  />
                </label>
                ${err && html`<div className="landing-err">${err}</div>`}
                <div className="landing-create-actions">
                  <button className="tbtn" disabled=${busyId === p.id} onClick=${() => { setEditingId(null); setEditLabel(""); setErr(null); }}>Cancel</button>
                  <button className="tbtn tbtn-primary" disabled=${busyId === p.id} onClick=${() => saveRename(p.id)}>
                    ${busyId === p.id ? "Saving…" : "Save"}
                  </button>
                </div>
              </div>
            ` : html`
              <div key=${p.id} className=${"landing-card landing-card-has-thumb" + (p.thumbnailPrototype && p.thumbnailPrototype.exists ? " landing-card-thumb-asset" : " landing-card-thumb-field")} onClick=${() => openProject(p.id, "workflow")} role="button" tabIndex=${0} onKeyDown=${e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openProject(p.id, "workflow"); } }}>
                <div className="landing-card-thumb">
                  ${p.thumbnailPrototype && p.thumbnailPrototype.exists
                    ? (p.thumbnailPrototype.screenshot === false
                        /* daemon says no capture on disk → straight to the live
                           iframe, no wasted 404 probe. Undefined (pre-restart
                           daemon) or true → try the PNG, onError falls back. */
                        ? html`<${LandingCardThumbIframe}
                            src=${"/" + p.thumbnailPrototype.path + "?project=" + encodeURIComponent(p.id)}
                            title=${"Preview of " + (p.thumbnailPrototype.label || p.thumbnailPrototype.id)}
                          />`
                        : html`<${LandingCardThumbShot}
                            projectId=${p.id}
                            version=${p.thumbnailPrototype.screenshotV || p.lastActivity || 0}
                            src=${"/" + p.thumbnailPrototype.path + "?project=" + encodeURIComponent(p.id)}
                            title=${"Preview of " + (p.thumbnailPrototype.label || p.thumbnailPrototype.id)}
                          />`)
                    : html`<${LandingCardField} seed=${p.id} hostRef=${null}/>`}
                </div>
                <div className="landing-card-body">
                <div className="landing-card-head">
                  <span className="landing-card-anchor" aria-hidden="true"></span>
                  <div className="landing-card-label">${p.label || p.id}</div>
                  <span className="landing-card-age" title=${"Last edited " + fmtActivity(p.lastActivity)}>${fmtActivity(p.lastActivity)}</span>
                  <div className="landing-card-actions">
                    <button
                      className="landing-card-action"
                      title="Rename"
                      disabled=${busyId === p.id}
                      onClick=${(e) => { e.stopPropagation(); setEditingId(p.id); setEditLabel(p.label || p.id); setErr(null); }}
                    ><${Icon.Pen}/></button>
                    <button
                      className="landing-card-action"
                      title="Duplicate (local copy - no LLM, renames all references)"
                      disabled=${busyId === p.id}
                      onClick=${(e) => { e.stopPropagation(); duplicateProject(p.id, p.label); }}
                    ><${Icon.Copy}/></button>
                    <button
                      className="landing-card-action landing-card-action-danger"
                      title="Delete (moves to .trash/)"
                      disabled=${busyId === p.id}
                      onClick=${(e) => { e.stopPropagation(); deleteProject(p.id, p.label); }}
                    ><${Icon.Trash}/></button>
                  </div>
                </div>
                ${p.label && p.label !== p.id ? html`<div className="landing-card-id">${p.id}</div>` : null}
                ${(p.starredPrototypes || []).length > 0 && html`
                  <div className="landing-card-stars">
                    <div className="landing-card-stars-head">
                      <span className="landing-card-stars-icon"><${Icon.Star}/></span>
                      <span>Starred prototypes</span>
                    </div>
                    <ul className="landing-card-stars-list">
                      ${p.starredPrototypes.map(sp => html`
                        <li key=${sp.id} className=${"landing-card-star-row" + (sp.exists ? "" : " is-missing")}>
                          <button
                            className="landing-card-star-btn"
                            title=${sp.exists
                              ? `Open ${sp.path} in a new tab (raw source, no editor chrome)`
                              : `${sp.path} - file no longer on disk. Star kept so you can re-create it; click to unstar.`}
                            onClick=${(e) => {
                              e.stopPropagation();
                              if (!sp.exists) return;
                              // v3.6 - Play from the landing always opens in a
                              // new tab. Earlier it replaced the landing in-
                              // place, which forced a full nav back through the
                              // shader-heavy landing every time the user wanted
                              // to compare prototypes.
                              // v3.7 - Go straight to the source URL instead of
                              // the editor's prototype-door view. The door
                              // wrapped the same source in an iframe with a
                              // back-chip + breadcrumb top bar; opening the
                              // source directly drops that chrome so the
                              // prototype is the only thing in the tab.
                              const branchPath = sp.id.split("/").map(encodeURIComponent).join("/");
                              const src = new URL(`/source/${branchPath}/?project=${encodeURIComponent(p.id)}`, window.location.href);
                              window.open(src.toString(), "_blank", "noopener");
                            }}
                          >
                            <span className="landing-card-star-glyph"><${Icon.Play}/></span>
                            <span className="landing-card-star-label">${sp.label || sp.id}</span>
                            ${sp.label && sp.label !== sp.id
                              ? html`<span className="landing-card-star-slug">${sp.id}</span>`
                              : null}
                          </button>
                          <button
                            className="landing-card-star-edit"
                            title=${sp.exists
                              ? `Open the editor on ${sp.path}`
                              : `Try to open the editor on ${sp.path} (file no longer on disk)`}
                            aria-label="Open editor"
                            onClick=${(e) => {
                              e.stopPropagation();
                              const url = new URL(window.location.href);
                              url.searchParams.set("project", p.id);
                              url.searchParams.set("prototype", sp.id);
                              url.searchParams.delete("branch");
                              url.searchParams.delete("view");
                              thNavigate(url.toString());
                            }}
                          ><${Icon.Canvas}/></button>
                        </li>
                      `)}
                    </ul>
                  </div>
                `}
                </div>
              </div>
            `)}
            ${filter && filtered.length === 0 && html`
              <div className="landing-empty landing-empty-mini">
                <div>No projects match "${filter}".</div>
                <button className="tbtn" onClick=${() => setFilter("")}>Clear filter</button>
              </div>
            `}
          </div>
        `}
        ${activeTab === "projects" && !onboardingCardShowing && html`
          <div className="landing-housekeeping">
            <button className="landing-hk-trigger" onClick=${() => setHousekeepingOpen(true)} title="Manage and permanently delete projects in the trash">
              <${Icon.Trash}/>
              <span className="landing-hk-trigger-label">Housekeeping</span>
              <span className="landing-hk-trigger-sub">empty trash · delete projects forever</span>
            </button>
          </div>
        `}
        ${housekeepingOpen && html`<${ProjectsHousekeeping} onClose=${() => setHousekeepingOpen(false)}/>`}
        </div>
      </main>
    </div>
  `;
}

/* ───────────────────────── Client-side navigation ─────────────────────────
   The list↔project round trip used to be a full `window.location.href`
   document reload every time, which produced the flash → wait → open beat:
   the browser blanks #root (flash), re-fetches the whole boot chain - 7 CDN
   scripts + the 61k-line app.js + the blocking data.js / layout / ds_bootstrap
   loads (wait) - then re-mounts React (open).

   We can skip ALL of that for the views that don't read the boot-captured
   `const D = window.EDITOR_DATA` - the projects landing (fetches /__workspace)
   and the workflow canvas (fetches workflow.json). For those we just push the
   new URL and let <Root> re-render in place. The editor + prototype views DO
   read `D` (captured once at script-eval and never reassignable), so any
   navigation whose DESTINATION is one of those still does a real reload, which
   re-runs data.js and refreshes `D`. */
function thReadNav() {
  try {
    const sp = new URL(window.location.href).searchParams;
    return {
      project: sp.get("project") || null,
      hasProject: !!sp.get("project"),
      view: sp.get("view") || null,
    };
  } catch {
    return { project: null, hasProject: false, view: null };
  }
}

// A destination is client-nav-safe iff it lands on the projects gallery
// (no ?project=) or the workflow canvas (?view=workflow) - the two surfaces
// that don't depend on the boot-captured `D`. Editor (project, no view) and
// prototype (?view=prototype) need a fresh `D` → full reload.
function thIsClientNavSafe(url) {
  try {
    const sp = new URL(url, window.location.href).searchParams;
    if (!sp.get("project")) return true;            // landing
    const v = sp.get("view") || null;
    return v === "workflow" || v === "usertesting"; // canvas + user testing page
  } catch {
    return false;
  }
}

// Boot veil - see index.html. Raised over the current document just before a
// full-reload navigation (so the last frame the user sees is a loading state,
// not a white blank), and on the freshly-loaded document until <Root> renders.
function showBootVeil() {
  try {
    let v = document.getElementById("boot-veil");
    if (!v) {
      v = document.createElement("div");
      v.id = "boot-veil";
      v.setAttribute("aria-hidden", "true");
      v.innerHTML = '<div class="boot-veil-spinner"></div>';
      document.body.appendChild(v);
    }
    v.classList.remove("boot-veil-hide");
  } catch {}
}
function hideBootVeil() {
  try {
    const v = document.getElementById("boot-veil");
    if (!v) return;
    v.classList.add("boot-veil-hide");
    // Drop it from the DOM after the fade so it never traps pointer events and
    // a later showBootVeil() rebuilds a clean one.
    setTimeout(() => { try { v.remove(); } catch {} }, 240);
  } catch {}
}

// Swap a client-nav-safe view in place: reset the per-project caches that were
// latched at boot, push the URL, and fire `th:navigate` so <Root> re-derives
// the view. Anything else falls back to a real document load - masked by the
// boot veil so editor / prototype entry reads as a continuous loading state
// rather than the old flash → blank → open beat.
function thNavigate(url) {
  const target = new URL(url, window.location.href).toString();
  if (!thIsClientNavSafe(target)) {
    showBootVeil();
    // Yield one frame so the veil actually paints on this document before the
    // browser tears it down; the new document shows the same veil immediately.
    try { requestAnimationFrame(() => { window.location.href = target; }); }
    catch { window.location.href = target; }
    return;
  }
  window.history.pushState({}, "", target);
  // activeProjectId() memoises ?project= on window.__TH_PROJECT - an UNkeyed
  // global latched to the project we're leaving - so clear it and let the
  // helper re-derive against the URL we just pushed. (The __TH_STARRED /
  // __TH_THUMB caches are keyed by project id, so they stay valid and are
  // left intact for reuse.)
  try { delete window.__TH_PROJECT; } catch { window.__TH_PROJECT = undefined; }
  try { window.dispatchEvent(new CustomEvent("th:navigate")); } catch {}
}

/* Back-to-landing helper. Clears every per-project URL bit (?project=,
   ?prototype=, ?view=) so the workspace boots back into the gallery.
   Single source of truth for "leave this project" - used by every
   top-level view that has a back chip. */
function backToProjects() {
  const url = new URL(window.location.href);
  url.searchParams.delete("project");
  url.searchParams.delete("prototype");
  url.searchParams.delete("branch");
  url.searchParams.delete("view");
  url.searchParams.delete("from");
  thNavigate(url.toString());
}

// Return to the workflow canvas for the active project - used when the editor
// was opened FROM workflow mode (the open carries ?from=workflow). Keeps the
// project, drops the prototype/branch/from markers, sets view=workflow.
function backToWorkflow() {
  const url = new URL(window.location.href);
  url.searchParams.delete("prototype");
  url.searchParams.delete("branch");
  url.searchParams.delete("from");
  url.searchParams.set("view", "workflow");
  thNavigate(url.toString());
}

// True when the editor was reached from the workflow canvas (the open stamps
// ?from=workflow). Drives the ProjectHomeButton's back target.
function cameFromWorkflow() {
  try { return new URLSearchParams(location.search).get("from") === "workflow"; }
  catch { return false; }
}

/* Phase 3.5a - Prototype door.
   Just the live source, full-page. No editor chrome, no frame model, no
   per-frame setupScript replay. The user clicks around inside the iframe as
   they would a real app. Branch is taken from ?branch= if present, else
   "main". The iframe URL flows through apiUrl() so workspace-mode routing
   (?project=) resolves source/<branch>/ to the active project's tree. */
function PrototypeDoor() {
  const params = new URL(window.location.href).searchParams;
  const branch = params.get("prototype") || params.get("branch") || "main";
  const project = params.get("project") || "";
  // Slug may be nested ("main/sketches") - encode each segment so the
  // path-separator survives the URL but everything else gets escaped.
  const branchPath = branch.split("/").map(encodeURIComponent).join("/");
  const src = apiUrl(`/source/${branchPath}/`);
  return html`
    <div className="proto-door">
      <div className="proto-door-bar">
        <button className="proto-door-back" onClick=${backToProjects} title="Back to projects">
          <span className="proto-door-back-arrow">←</span>
          <span>Projects</span>
        </button>
        <div className="proto-door-meta">
          ${project && html`<span className="proto-door-meta-project">${project}</span>`}
          <span className="proto-door-meta-sep">/</span>
          <code className="proto-door-meta-path">source/${branch}/</code>
        </div>
        <div className="proto-door-actions">
          <a className="proto-door-open" href=${src} target="_blank" rel="noopener">Open in new tab ↗</a>
        </div>
        <${SurfaceNav}/>
      </div>
      <iframe className="proto-door-iframe" src=${src} title="Prototype"/>
    </div>
  `;
}

/* Phase 3.5b - Workflow canvas.
   Endless pan/zoom canvas scoped to one project. Loads/persists
   <project>/workflow/workflow.json via /__workflow GET/POST. Library rail
   on the left lists draggable prototypes (one per branch); drop on canvas
   creates a prototype-instance node that iframes source/<branch>/ live.
   Expose flow + asset / skill / prompt nodes + edges arrive in 3.5c/3.5d.
   The lock semantics (instance pinned to its prototype-internal page) plug
   in then too - for 3.5b each instance is just a free-floating iframe. */
// v3.4.10 - Deprecated model ID live-resolution.
// Each row maps "model literal that no longer works at the provider's API"
// → "the current replacement on the same provider that does the closest
// thing." node.model is stored byte-identical to whatever the user picked,
// but every READER resolves through _resolveLiveModel() so the chip, the
// dropdown, and the run dispatcher all see the live ID. This is the
// "linked" semantic - the catalog is the source of truth, not the saved
// string. Picking a non-deprecated ID via the dropdown writes that literal;
// the dropdown's "selected" highlight reflects the resolved value so
// deprecated strings appear as their current replacement everywhere.
// Hard-shutoff deprecations (the bare-luma 502, DALL·E 2/3 sunsets, etc.)
// are the ONES THIS MAP MUST CATCH - otherwise dispatch hits a dead
// endpoint. Soft deprecations are mapped for catalog hygiene.
const _DEPRECATED_MODEL_MIGRATIONS = {
  // OpenAI - DALL·E shut down May 12, 2026; gpt-image-1 deprecates Oct 23, 2026
  "dall-e-2":                                              "gpt-image-2",
  "dall-e-3":                                              "gpt-image-2",
  "gpt-image-1":                                           "gpt-image-2",
  // Anthropic - dated aliases → undated current (the dated ones still
  // respond for now but the un-dated ID is what the catalog ships)
  "claude-sonnet-4-5-20250929":                            "claude-sonnet-4-6",
  "claude-haiku-4-5-20251001":                             "claude-haiku-4-5",
  "claude-sonnet-4-5":                                     "claude-sonnet-4-6",
  // fal.ai video - bare Luma is the URGENT one (returns 502 "deprecated")
  "fal-ai/luma-dream-machine":                             "fal-ai/veo3.1",
  "fal-ai/kling-video/v1/standard":                        "fal-ai/kling-video/v2.5-turbo/pro/text-to-video",
  "fal-ai/kling-video/v1/pro":                             "fal-ai/kling-video/v2.5-turbo/pro/text-to-video",
  "fal-ai/minimax/hailuo-02/standard/text-to-video":       "fal-ai/minimax/hailuo-2.3-fast/pro/text-to-video",
  // fal.ai image - Ideogram v2 still works but v3 is current
  "fal-ai/ideogram/v2":                                    "fal-ai/ideogram/v3",
};
// Provider migrations applied IN PARALLEL when a model's replacement
// requires a different provider. None of our current rows cross providers,
// so this is empty for now - kept as a hook for future cases.
const _DEPRECATED_MODEL_PROVIDER = {};
// Single source of truth for "saved model string → live model ID."
// Pass any string (including empty/null); the function returns the live ID
// the caller should DISPLAY and DISPATCH. Empty / falsy / unknown values
// pass through unchanged so callers can OR-chain with their own defaults:
//   const live = _resolveLiveModel(node.model) || skillSpec.defaultModel;
function _resolveLiveModel(raw) {
  if (typeof raw !== "string" || !raw) return raw;
  const mapped = _DEPRECATED_MODEL_MIGRATIONS[raw];
  return mapped || raw;
}
// Companion: did the resolver swap the input? Used by the UI to render a
// "(was: <oldId>)" hint in tooltips so the user knows the chip is showing
// the live ID rather than what's literally saved on the node.
function _modelWasDeprecated(raw) {
  return typeof raw === "string" && !!_DEPRECATED_MODEL_MIGRATIONS[raw];
}

// v2.33 - list of editable fields the user can mutate on each node kind.
// The reload-merge consults a saved-snapshot map for these fields; a field
