    const nums = (raw || "").trim().split(/[\s,]+/).map(Number).filter(n => Number.isFinite(n));
    let d = ""; for (let i = 0; i + 1 < nums.length; i += 2) d += (i === 0 ? "M" : "L") + X(nums[i]) + " " + Y(nums[i + 1]) + " ";
    return d ? (d + (close ? "Z" : "")) : null;
