    const ring = [];
    for (let i = 0; i < n; i++) {
      const p = tmp.getPointAtLength((i / n) * sl);
      ring.push([p.x, p.y]);
    }
    ring.push([ring[0][0], ring[0][1]]);
    rings.push(ring);
